// reemplazarlo todo (importar, restaurar, cargar demo). Para cambiar uno o dos
// productos usa guardarProductos(lista, ids), justo debajo.
const saveProductos = v  => { v = _sanearLista('productos', v); if(Array.isArray(v)) v.forEach(_normalizeProducto); _safeSetLS('axon_productos', JSON.stringify(v)); _productosCache = v; _productosDirty = false; _productosMap = null; if (!isSyncingFromCloud()) setSB('productos', v); triggerAutoPublishCatalog(); };

// ── v95: guardar SOLO los productos que cambian ─────────────────────────────
// El 16/08 se perdió el inventario de un día entero por esto. Alguien tocó el
// stock desde un segundo teléfono y, en vez de subir ese producto, subió su
// copia COMPLETA del catálogo — que llevaba horas sin refrescarse, porque la
// lista de productos solo se baja cada 5 minutos y nunca con la app en segundo
// plano. El upsert de la nube no compara fechas: el último que escribe gana.
// Así que un teléfono desactualizado podía reponer el inventario de la mañana
// con una sola pulsación, y ni siquiera hacía falta mala suerte.
//
// Ahora cada cambio manda solo las filas tocadas. Las demás ni se mencionan, así
// que lo que otro dispositivo haya hecho mientras tanto sobrevive intacto.
// Un id que ya no está en la lista se manda como null y eso SÍ borra la fila en
// la nube — antes, borrar un producto solo lo quitaba del teléfono y volvía a
// aparecer en la siguiente sincronización.
function guardarProductos(lista, ids) {
  if (Array.isArray(lista)) lista.forEach(_normalizeProducto);
  _safeSetLS('axon_productos', JSON.stringify(lista));
  _productosCache = lista; _productosDirty = false; _productosMap = null;
  if (!isSyncingFromCloud()) {
    const porId = new Map();
    (lista || []).forEach(p => { if (p && p.id != null) porId.set(String(p.id), p); });
    const cambios = {};
    (ids || []).forEach(id => {
      if (id == null) return;
      const k = String(id);
      cambios[k] = porId.has(k) ? porId.get(k) : null;   // null = borrar la fila
    });
    if (Object.keys(cambios).length) _enqueueSB('productos', cambios, 'update');
  }
  triggerAutoPublishCatalog();
}

const getCategorias = () => { if (_categoriasDirty || !_categoriasCache) { try { _categoriasCache = _sanearLista('categorias', JSON.parse(localStorage.getItem('axon_categorias') || '[]')); } catch(e) { _categoriasCache = []; } _categoriasDirty = false; } return _categoriasCache; };
// ⚠️ Sube la lista entera: solo para importar/restaurar/demo.
const saveCategorias= v  => { v = _sanearLista('categorias', v); _safeSetLS('axon_categorias', JSON.stringify(v)); _categoriasCache = v; _categoriasDirty = false; if (!isSyncingFromCloud()) setSB('categorias', v); };
function guardarCategorias(lista, ids) {
  _guardarFilas('axon_categorias', 'categorias', lista, ids, l => { _categoriasCache = l; _categoriasDirty = false; });
}

const getConfig     = () => { if (_configDirty || !_configCache) { try { _configCache = JSON.parse(localStorage.getItem('axon_config') || '{}'); } catch(e) { _configCache = {}; } _configDirty = false; } return _configCache; };
// v140: la config sube SOLO lo que cambió, y se junta con la de la nube. Antes
// subía entera: un equipo con una copia vieja (un admin recién abierto, la
// tasa que se refresca sola cada 3 h) borraba lo que había puesto otro —la
// auditoría vio desaparecer el historial de ganadores, el ciclo, la meta, el
// repositorio y la llave de las claves—. Una clave que se quita viaja como null.
const saveConfig    = v  => {
  const antes = (() => { try { return _configCache || JSON.parse(localStorage.getItem('axon_config') || '{}'); } catch(e) { return {}; } })();
  _safeSetLS('axon_config', JSON.stringify(v)); _configCache = v; _configDirty = false;
  if (isSyncingFromCloud()) return;
  const parche = {};
  const ahora = JSON.parse(JSON.stringify(v || {}));   // lo que de verdad se guarda (sin undefined)
  new Set([...Object.keys(antes || {}), ...Object.keys(ahora)]).forEach(k => {
    if (k === 'ghToken') return;                         // el token nunca sale del teléfono
    const a = JSON.stringify(antes ? antes[k] : undefined), d = JSON.stringify(ahora[k]);
    if (a !== d) parche[k] = (k in ahora) ? ahora[k] : null;
  });
  if (Object.keys(parche).length) setSB('config', parche, 'update');
};

// ══════════════════════════════════════════
//  v80 · MARCA / DISEÑO (apartado 🎨 Diseño del admin)
// ══════════════════════════════════════════
// La identidad del negocio —nombre, logo y paleta de colores— vive en un
// documento `marca` de la tabla meta (misma mecánica que `config`). Lo edita
// el admin desde el panel 🎨 Diseño y baja al resto de teléfonos por el
// sondeo normal. Con esto el programa se adapta a cualquier negocio sin
// tocar código: cada tienda pone su nombre, su logo y sus colores.
//
// Estructura del documento:
//   { nombre:'Mi Tienda', subtitulo:'VENTAS DE CONFIANZA',
//     logo:'data:image/…',      ← imagen recortada en círculo (unos KB)
//     logoEmoji:'🔥',           ← alternativa sin peso: un emoji
//     paleta:'azul'|'custom', color:'#22c55e' }
// Todo es opcional: lo que falta sale del estilo original (AXONTECH, teal).
const MARCA_PALETAS = [
  { id:'teal',      nombre:'Teal',      base:'#006d8a' },   // el original
  { id:'oceano',    nombre:'Océano',    base:'#2563eb' },
  { id:'indigo',    nombre:'Índigo',    base:'#4f46e5' },
  { id:'violeta',   nombre:'Violeta',   base:'#7c3aed' },
  { id:'esmeralda', nombre:'Esmeralda', base:'#059669' },
  { id:'verde',     nombre:'Verde',     base:'#16a34a' },
  { id:'naranja',   nombre:'Naranja',   base:'#ea580c' },
  { id:'rojo',      nombre:'Rojo',      base:'#dc2626' },
  { id:'rosa',      nombre:'Rosa',      base:'#db2777' },
  { id:'grafito',   nombre:'Grafito',   base:'#475569' }
];
const _MARCA_LOGO_OK  = /^data:image\/(png|jpe?g|webp|gif);base64,[A-Za-z0-9+/=]+$/;
const _MARCA_LOGO_MAX = 40000;   // la celda de la hoja admite ~45.000 caracteres

// ── utilidades de color (hex ⇄ hsl, mezclas) ─────────────────────────────
function _maHexARgb(hex){
  hex = String(hex || '').replace('#', '');
  if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
  const n = parseInt(hex.slice(0, 6), 16);
  if (isNaN(n)) return null;
  return { r:(n >> 16) & 255, g:(n >> 8) & 255, b:n & 255 };
}
function _maRgbAHsl(r, g, b){
  r /= 255; g /= 255; b /= 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b), d = max - min;
  let h = 0;
  if (d) {
    if (max === r) h = ((g - b) / d) % 6;
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h *= 60; if (h < 0) h += 360;
  }
  const l = (max + min) / 2;
  const s = d ? d / (1 - Math.abs(2 * l - 1)) : 0;
  return { h, s:s * 100, l:l * 100 };
}
function _maHslAHex(h, s, l){
  s /= 100; l /= 100;
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = l - c / 2;
  let r, g, b;
  if (h < 60)       { r = c; g = x; b = 0; }
  else if (h < 120) { r = x; g = c; b = 0; }
  else if (h < 180) { r = 0; g = c; b = x; }
  else if (h < 240) { r = 0; g = x; b = c; }
  else if (h < 300) { r = x; g = 0; b = c; }
  else              { r = c; g = 0; b = x; }
  const f = v => Math.round((v + m) * 255).toString(16).padStart(2, '0');
  return '#' + f(r) + f(g) + f(b);
}
function _maMezcla(hexA, hexB, t){
  const a = _maHexARgb(hexA), b = _maHexARgb(hexB);
  if (!a || !b) return hexA;
  const f = (x, y) => Math.round(x + (y - x) * t).toString(16).padStart(2, '0');
  return '#' + f(a.r, b.r) + f(a.g, b.g) + f(a.b, b.b);
}
// De un color base salen los 5 tonos que usa la app en claro y en oscuro.
// Los valores calzan razonablemente con el teal original (afinados a mano),
// así que cualquier paleta queda con la misma lógica de contraste.
function _maDerivarColores(base){
  const rgb = _maHexARgb(base);
  if (!rgb) return null;
  const { h, s, l } = _maRgbAHsl(rgb.r, rgb.g, rgb.b);
  const cs = clamp_ => Math.max(0, Math.min(100, clamp_));
  const dk = _maHslAHex(h, cs(s * 1.02), cs(l * 0.68));
  const accent = _maHslAHex(h, cs(s), Math.min(l * 1.55 + 6, 64));
  const oscuro = '#0f172a';
  return {
    base, dk, accent,
    lt: _maMezcla(base, '#ffffff', 0.90),
    bd: _maMezcla(base, '#ffffff', 0.75),
    dark: {
      blue:   _maHslAHex(h, cs(s), 44),
      blueDk: _maHslAHex(h, cs(s), 56),
      accent: _maHslAHex(h, cs(s), 56),
      lt:     _maMezcla(base, oscuro, 0.86),
      bd:     _maMezcla(base, oscuro, 0.72)
    },
    rgbBase: rgb.r + ', ' + rgb.g + ', ' + rgb.b
  };
}

// ── caché local (axon_marca) + acceso ────────────────────────────────────
let _marcaCache = null, _marcaDirty = true;
const getMarca = () => {
  if (_marcaDirty || _marcaCache == null) {
    try { const raw = JSON.parse(localStorage.getItem('axon_marca') || 'null'); _marcaCache = (raw && typeof raw === 'object') ? raw : null; }
    catch (e) { _marcaCache = null; }
    _marcaDirty = false;
  }
  return _marcaCache;
};

// Limpia y valida el documento: nada de caracteres de control, longitud
// acotada, logo en dataURL conocida y dentro del límite de la hoja, paleta
// conocida. Si no queda nada útil devuelve null (→ estilo de fábrica).
function _marcaNormalizada(m){
  if (!m || typeof m !== 'object') return null;
  const limpiar = (v, n) => String(v == null ? '' : v).replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, n);
  const doc = {};
  const nombre = limpiar(m.nombre, 22), sub = limpiar(m.subtitulo, 36);
  if (nombre) doc.nombre = nombre;
  if (sub) doc.subtitulo = sub;
  if (MARCA_PALETAS.some(p => p.id === m.paleta)) doc.paleta = m.paleta;
  else if (m.paleta === 'custom' && _COLOR_OK.test(String(m.color || ''))) {
    doc.paleta = 'custom'; doc.color = String(m.color).toLowerCase();
  }
  const emoji = limpiar(m.logoEmoji, 8);
  if (emoji) doc.logoEmoji = emoji;
  const logo = String(m.logo || '');
  if (logo && _MARCA_LOGO_OK.test(logo) && logo.length <= _MARCA_LOGO_MAX) doc.logo = logo;
  return Object.keys(doc).length ? doc : null;
}
const _marcaNombre  = m => (m && m.nombre) || 'AXONTECH';
const _marcaSubtitulo = m => (m && m.subtitulo) || '';
// Color base elegido (null = teal original, no se inyecta nada)
function _marcaBase(m){
  if (!m || !m.paleta) return null;
  if (m.paleta === 'custom') return _COLOR_OK.test(String(m.color || '')) ? String(m.color) : null;
  const p = MARCA_PALETAS.find(p => p.id === m.paleta);
  return p ? p.base : null;
}
// Contenido del icono cuadrado de la cabecera: logo, emoji o iniciales.
function _marcaIconoInner(m, nombre){
  if (m && m.logo) return `<img src="${m.logo}" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:inherit;display:block;">`;
  if (m && m.logoEmoji) return escapeHTML(m.logoEmoji);
  const palabras = String(nombre).split(/\s+/).filter(Boolean);
  let ini = '';
  if (palabras.length >= 2) ini = palabras[0][0] + palabras[1][0];
  else ini = String(nombre).replace(/[^A-Za-z0-9ÁÉÍÓÚÑáéíóúñüÜ]/g, '').slice(0, 2);
  return escapeHTML((ini || 'AX').toUpperCase());
}

// ── variables CSS del tema ───────────────────────────────────────────────
// Se inyecta una hoja de estilos al FINAL del <head>: mismas especificidades
// que :root y body.dark de app.css, pero última → gana. Si la paleta es la
// original se retira, y app.css manda como siempre.
function _marcaAplicarVars(base){
  const c = _maDerivarColores(base);
  if (!c) return;
  let st = document.getElementById('axonMarcaVars');
  if (!st) {
    st = document.createElement('style');
    st.id = 'axonMarcaVars';
    document.head.appendChild(st);
  }
  st.textContent = `:root{--blue:${c.base};--blue-dk:${c.dk};--blue-lt:${c.lt};--blue-bd:${c.bd};--accent:${c.accent};}` +
    `body.dark{--blue:${c.dark.blue};--blue-dk:${c.dark.blueDk};--blue-lt:${c.dark.lt};--blue-bd:${c.dark.bd};--accent:${c.dark.accent};}`;
}
function _marcaQuitarVars(){
  const st = document.getElementById('axonMarcaVars');
  if (st) st.parentNode.removeChild(st);
}

// ── favicon + icono iOS generados al vuelo ───────────────────────────────
function _marcaFaviconPoner(url){
  ['icon', 'apple-touch-icon'].forEach(rel => {
    let l = document.querySelector(`link[rel="${rel}"]`);
    if (!l) { l = document.createElement('link'); l.rel = rel; document.head.appendChild(l); }
    l.href = url;
  });
}
function _marcaFavicon(m, base, nombre){
  try {
    const dibujar = tam => {
      const c = document.createElement('canvas'); c.width = c.height = tam;
      const ctx = c.getContext('2d'); if (!ctx) return null;
      const r = tam * 0.22;
      ctx.beginPath();
      ctx.moveTo(r, 0);
      ctx.arcTo(tam, 0, tam, tam, r); ctx.arcTo(tam, tam, 0, tam, r);
      ctx.arcTo(0, tam, 0, 0, r); ctx.arcTo(0, 0, tam, 0, r);
      ctx.closePath();
      ctx.fillStyle = base || '#006d8a'; ctx.fill();
      if (m && m.logo) {
        const img = new Image();
        img.onload = () => {
          ctx.save(); ctx.clip();
          ctx.drawImage(img, 0, 0, tam, tam);
          ctx.restore();
          try { _marcaFaviconPoner(c.toDataURL('image/png')); } catch (e) {}
        };
        img.src = m.logo;
        return null;   // el favicon lo pone el onload
      }
      if (m && m.logoEmoji) {
        ctx.font = Math.round(tam * 0.62) + 'px serif';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(m.logoEmoji, tam / 2, tam * 0.56);
      } else {
        const palabras = String(nombre).split(/\s+/).filter(Boolean);
        let ini = palabras.length >= 2 ? (palabras[0][0] + palabras[1][0])
                                       : String(nombre).replace(/[^A-Za-z0-9ÁÉÍÓÚÑáéíóúñüÜ]/g, '').slice(0, 2);
        ctx.fillStyle = '#fff';
        ctx.font = '900 ' + Math.round(tam * 0.42) + 'px Sora,Arial,sans-serif';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText((ini || 'AX').toUpperCase(), tam / 2, tam * 0.55);
      }
      return c.toDataURL('image/png');
    };
    const d96 = dibujar(96); if (d96) _marcaFaviconPoner(d96);
    if (!(m && m.logo)) { const d180 = dibujar(180); if (d180) { let l = document.querySelector('link[rel="apple-touch-icon"]'); if (l) l.href = d180; } }
  } catch (e) { /* sin canvas o sin imagen: queda el favicon de siempre */ }
}

// ── manifest dinámico (nombre e icono al instalar la PWA) ────────────────
function _marcaManifest(m, base, nombre){
  try {
    const orig = document.querySelector('link[rel="manifest"]');
    if (!orig || !orig.href || !/^https?:|^blob:/.test(location.href)) return;   // file:// no tiene fetch cómodo
    fetch(orig.href).then(r => r.ok ? r.json() : null).then(mf => {
      if (!mf || typeof mf !== 'object') return;
      mf.name = nombre + ' · Gestión de Ventas';
      mf.short_name = nombre;
      mf.theme_color = base || '#006d8a';
      mf.background_color = base || '#006d8a';
      if (m && m.logo) {
        mf.icons = [
          { src:m.logo, sizes:'192x192', type:'image/png', purpose:'any' },
          { src:m.logo, sizes:'512x512', type:'image/png', purpose:'maskable' }
        ];
      }
      const blob = URL.createObjectURL(new Blob([JSON.stringify(mf)], { type:'application/manifest+json' }));
      orig.href = blob;
    }).catch(() => {});
  } catch (e) { /* opcional: si falla, queda el manifest.json de fábrica */ }
}

// ── aplicar la marca a la página ─────────────────────────────────────────
// Corre en index (gestor) y admin. Repinta cabecera, splash, título,
// favicon y colores. `m` puede ser null → todo vuelve al estilo de fábrica.
function aplicarMarca(m, opts){
  try {
    m = _marcaNormalizada(m);
    const nombre = _marcaNombre(m);
    const base = _marcaBase(m);
    const pag = (document.body && document.body.getAttribute('data-page')) || '';
    // 1) colores del tema
    if (base) _marcaAplicarVars(base); else _marcaQuitarVars();
    // 2) color del navegador (barra de estado)
    const tc = document.querySelector('meta[name="theme-color"]');
    if (tc) tc.setAttribute('content', base || '#006d8a');
    // 3) splash: gradiente + logo mientras carga
    const sp = document.getElementById('axon-splash');
    if (sp) {
      const c = _maDerivarColores(base || '#006d8a');
      if (c) sp.style.background = `linear-gradient(135deg, ${c.dk} 0%, ${c.base} 100%)`;
      const lg = sp.querySelector('.axon-splash-logo');
      if (lg) {
        if (m && m.logo) lg.innerHTML = `<img src="${m.logo}" alt="" style="width:84px;height:84px;object-fit:cover;border-radius:24px;display:block;margin:0 auto 16px;box-shadow:0 6px 24px rgba(0,0,0,.35);border:2px solid rgba(255,255,255,.3);">`;
        else if (m && m.logoEmoji) { lg.textContent = m.logoEmoji; lg.style.letterSpacing = '0'; }
        else { lg.textContent = nombre; lg.style.letterSpacing = ''; }
      }
    }
    // 4) cabecera: nombre, lema e icono
    document.querySelectorAll('header .brand-name').forEach(el => { el.textContent = nombre; });
    const subDef = (m && m.subtitulo) || (pag === 'admin' ? 'PANEL ADMIN' : 'GESTIÓN DE VENTAS');
    document.querySelectorAll('header .brand-sub').forEach(el => { el.textContent = subDef; });
    document.querySelectorAll('header .brand-icon').forEach(el => {
      el.innerHTML = _marcaIconoInner(m, nombre);
      if (m && m.logo) { el.style.background = 'rgba(255,255,255,.2)'; }
    });
    // 5) título de la pestaña
    document.title = pag === 'admin' ? `${nombre} · Admin` : `${nombre} · Gestión de Ventas`;
    const mt = document.querySelector('meta[name="apple-mobile-web-app-title"]');
    if (mt) mt.setAttribute('content', pag === 'admin' ? `${nombre} Admin` : nombre);
    // 6) favicon + manifest
    _marcaFavicon(m, base, nombre);
    _marcaManifest(m, base, nombre);
  } catch (e) {
    console.warn('[marca] no se pudo aplicar el diseño:', e && e.message);
  }
}

// ══════════════════════════════════════════
//  v80 · PANEL 🎨 DISEÑO (admin)
// ══════════════════════════════════════════
// Borrador de edición: se toca aquí y nada se guarda hasta 💾 Guardar diseño.
let _dnBorrador = null;

function renderDisenoUI(){
  const actual = _marcaNormalizada(getMarca());
  _dnBorrador = actual ? { ...actual } : {};
  const el = id => document.getElementById(id);
  if (el('dn-nombre')) el('dn-nombre').value = _dnBorrador.nombre || '';
  if (el('dn-sub'))    el('dn-sub').value = _dnBorrador.subtitulo || '';
  if (el('dn-emoji'))  el('dn-emoji').value = _dnBorrador.logoEmoji || '';
  if (el('dn-color'))  el('dn-color').value = _marcaBase(_dnBorrador) || '#006d8a';
  _dnPintaPaletas();
  _dnRefresca();
}
function _dnPintaPaletas(){
  const cont = document.getElementById('dn-paletas');
  if (!cont) return;
  const activa = _dnBorrador.paleta || 'teal';
  const swatch = (id, nombre, dots, extra) => `
    <button type="button" onclick="_dnPaleta('${id}')" style="display:flex;flex-direction:column;align-items:center;gap:6px;padding:10px 4px;border:2px solid ${activa === id ? 'var(--blue)' : 'var(--border)'};border-radius:14px;background:var(--surface);cursor:pointer;">
      <span style="display:flex;gap:3px;">${dots}</span>
      <span style="font-size:10.5px;font-weight:700;color:var(--text);">${nombre}</span>
    </button>`;
  cont.innerHTML = MARCA_PALETAS.map(p => {
    const c = _maDerivarColores(p.base);
    return swatch(p.id, p.nombre,
      `<span style="width:14px;height:14px;border-radius:50%;background:${p.base};"></span>` +
      `<span style="width:14px;height:14px;border-radius:50%;background:${c.dk};"></span>` +
      `<span style="width:14px;height:14px;border-radius:50%;background:${c.accent};"></span>`);
  }).join('') + swatch('custom', 'Personalizada',
      `<span style="width:48px;height:14px;border-radius:100px;background:linear-gradient(90deg,#006d8a,#7c3aed,#dc2626,#ea580c);display:inline-block;"></span>`);
}
function _dnRefresca(){
  const m = _dnBorrador || {};
  const nombre = (m.nombre || '').trim() || 'AXONTECH';
  const sub = (m.subtitulo || '').trim() || 'GESTIÓN DE VENTAS';
  const base = _marcaBase(m) || '#006d8a';
  const el = id => document.getElementById(id);
  // preview de cabecera
  const ic = el('dn-prev-icon');
  if (ic) { ic.innerHTML = _marcaIconoInner(m, nombre); }
  const pn = el('dn-prev-nombre'); if (pn) pn.textContent = nombre;
  const ps = el('dn-prev-sub');    if (ps) ps.textContent = sub;
  const card = el('dn-prev-card');
  if (card) {
    card.style.background = `linear-gradient(135deg, ${_maMezcla(base, '#000000', 0.32)} 0%, ${base} 100%)`;
    card.style.transition = 'background .25s ease';
  }
  const bb = el('dn-prev-btn');
  if (bb) { bb.style.background = base; bb.style.transition = 'background .25s ease'; }
  // chip del logo
  const lp = el('dn-logo-prev');
  if (lp) {
    if (m.logo) lp.innerHTML = `<img src="${m.logo}" alt="" style="width:64px;height:64px;border-radius:50%;object-fit:cover;border:2px solid var(--border);">`;
    else if (m.logoEmoji) lp.innerHTML = `<span style="font-size:40px;line-height:64px;">${escapeHTML(m.logoEmoji)}</span>`;
    else lp.innerHTML = `<span style="font-size:10px;color:var(--text-muted);text-align:center;line-height:1.4;">Sin logo<br>(se usan las iniciales)</span>`;
  }
}
function _dnNombre(el){ if (_dnBorrador) _dnBorrador.nombre = el.value; _dnRefresca(); }
function _dnSub(el){ if (_dnBorrador) _dnBorrador.subtitulo = el.value; _dnRefresca(); }
function _dnEmoji(el){ if (_dnBorrador) { _dnBorrador.logoEmoji = String(el.value || '').trim(); _dnBorrador.logo = ''; } _dnRefresca(); }
function _dnLogoQuitar(){
  if (_dnBorrador) { _dnBorrador.logo = ''; _dnBorrador.logoEmoji = ''; }
  const e = document.getElementById('dn-emoji'); if (e) e.value = '';
  _dnRefresca();
}
function _dnPaleta(id){
  if (!_dnBorrador) return;
  if (id === 'custom') {
    const ci = document.getElementById('dn-color');
    _dnBorrador.paleta = 'custom';
    _dnBorrador.color = (ci && ci.value) || '#006d8a';
  } else {
    _dnBorrador.paleta = id;
    delete _dnBorrador.color;
  }
  _dnPintaPaletas(); _dnRefresca();
}
function _dnColor(v){
  if (!_dnBorrador) return;
  _dnBorrador.paleta = 'custom';
  _dnBorrador.color = v;
  _dnPintaPaletas(); _dnRefresca();
}
// Subida de logo: recorte centrado a 256px y compresión progresiva hasta
// entrar en el límite de la celda de la hoja (~40.000 caracteres).
function _dnLogoElegir(input){
  const f = input.files && input.files[0];
  if (!f) return;
  if (!/^image\//.test(f.type)) { showToast('Ese archivo no es una imagen'); input.value = ''; return; }
  const fr = new FileReader();
  fr.onload = () => {
    const img = new Image();
    img.onload = () => {
      try {
        const lado = Math.min(img.width, img.height);
        const c = document.createElement('canvas'); c.width = c.height = 256;
        const ctx = c.getContext('2d');
        ctx.drawImage(img, (img.width - lado) / 2, (img.height - lado) / 2, lado, lado, 0, 0, 256, 256);
        let url = c.toDataURL('image/webp', 0.85);
        if (!/^data:image\/webp/.test(url)) url = c.toDataURL('image/jpeg', 0.85);
        if (url.length > _MARCA_LOGO_MAX) url = c.toDataURL('image/jpeg', 0.7);
        if (url.length > _MARCA_LOGO_MAX) {
          const c2 = document.createElement('canvas'); c2.width = c2.height = 160;
          const ctx2 = c2.getContext('2d');
          ctx2.drawImage(img, (img.width - lado) / 2, (img.height - lado) / 2, lado, lado, 0, 0, 160, 160);
          url = c2.toDataURL('image/jpeg', 0.72);
        }
        if (url.length > _MARCA_LOGO_MAX) { showToast('La imagen es demasiado grande — prueba con otra más sencilla'); input.value = ''; return; }
        if (_dnBorrador) { _dnBorrador.logo = url; _dnBorrador.logoEmoji = ''; }
        const e = document.getElementById('dn-emoji'); if (e) e.value = '';
        _dnRefresca();
        showToast('🖼 Logo listo — pulsa 💾 Guardar diseño');
      } catch (err) { showToast('No se pudo procesar la imagen'); }
      input.value = '';
    };
    img.onerror = () => { showToast('No se pudo leer la imagen'); input.value = ''; };
    img.src = fr.result;
  };
  fr.readAsDataURL(f);
}
function _dnGuardar(){
  if (!_dnBorrador) _dnBorrador = {};
  const doc = _marcaNormalizada(_dnBorrador);
  try {
    if (doc) { _safeSetLS('axon_marca', JSON.stringify(doc)); _marcaCache = doc; _marcaDirty = false; }
    else { try { localStorage.removeItem('axon_marca'); } catch (e) {} _marcaCache = null; _marcaDirty = false; }
    aplicarMarca(doc);
    if (!isSyncingFromCloud()) {
      if (doc) setSB('marca', doc);
      else _enqueueSB('marca', null, 'remove');   // borrado: los demás teléfonos vuelven al estilo de fábrica
    }
    try { _logAudit('diseno_actualizado', doc ? (doc.nombre || '') : '(restaurado)'); } catch (e) {}
    showToast('✅ Diseño guardado — llegará al resto de teléfonos en unos minutos');
    const st = document.getElementById('dn-status');
    if (st) st.textContent = 'Guardado a las ' + new Date().toLocaleTimeString() + ' · el catálogo público toma el estilo nuevo la próxima vez que se publique';
  } catch (e) {
    showToast('No se pudo guardar el diseño: ' + (e && e.message || e));
  }
}
function _dnRestaurar(){
  if (!confirm('¿Devolver el estilo de fábrica (nombre AXONTECH, sin logo y paleta teal)?')) return;
  _dnBorrador = {};
  _dnGuardar();
  renderDisenoUI();
}

// GitHub token helper — el token NUNCA se sincroniza a la nube.
// Vive solo en localStorage del dispositivo admin para evitar que gestores
// u otros dispositivos lo lean. Ver AUDITORIA-AXONTECH.md CRÍTICO 3.
const ghToken = () => { try { return localStorage.getItem('axon_gh_token') || ''; } catch(e) { return ''; } };

// Helper para escribir el estado de GitHub en AMBOS bloques (catálogo + config).
// Antes solo se actualizaba el primero por el ID duplicado. Ver AUDITORIA-AXONTECH.md ALTO 12.
const setGhStatus = html => ['ghSyncStatus','ghSyncStatus2'].forEach(i => {
  const el = document.getElementById(i);
  if (el) el.innerHTML = html;
});

const getNotifs     = () => { if (_notifsDirty || !_notifsCache) { try { _notifsCache = _sanearLista('notifs', JSON.parse(localStorage.getItem('axon_notifs') || '[]')); } catch(e) { _notifsCache = []; } _notifsDirty = false; } return _notifsCache; };
const saveNotifs    = v  => { v = _sanearLista('notifs', v); _safeSetLS('axon_notifs', JSON.stringify(v)); _notifsCache = v; _notifsDirty = false; if (!isSyncingFromCloud()) setSB('notifs', v); };

// ══════════════════════════════════════════
//  AUTO-PUBLISH CATALOG TO GITHUB
// ══════════════════════════════════════════
let _catalogPublishTimer = null;
function triggerAutoPublishCatalog() {
  const cfg = getConfig();
  if (!cfg.ghAutoPublishCatalog || !ghToken() || !cfg.ghRepo) return;
  clearTimeout(_catalogPublishTimer);
  _catalogPublishTimer = setTimeout(async () => {
    try {
      const html = buildCatalogHTML();
      if (html) await publishCatalogToGitHub(html);
    } catch(e) { console.error('Auto-publish catalog error:', e); }
  }, 5000);
}

function buildCatalogHTML() {
  const cats=getCategorias();
  // v139: `let` — más abajo se rehace con las categorías; con `const` fallaba
  // siempre que hubiera categorías y el catálogo público no se generaba.
  // FIX catálogo: solo productos DISPONIBLES. Antes solo excluía stock=0
  // (agotados) y los totalmente reservados se colaban al catálogo público.
  // Mismo criterio que la sección "Disponibles" del panel: stock>0 y no
  // totalmente reservado (_isFullyReserved = lo apartado a mano + vales).
  let allProds=getProductos().filter(p=>(p.stock||0)>0 && !_isFullyReserved(p));
  if(!allProds.length) return null;
  // ── v28 BUGFIX: Asignar catId por nombre si el producto no lo tiene ──
  // Algunos productos vienen de productos.json con campo 'categoria' (string)
  // pero sin 'catId'. Necesitamos mapear el nombre de categoría al ID
  // para que el catálogo agrupe correctamente los productos.
  // v36: Shallow clone to avoid mutating cached product objects
  if(cats.length){
    const catNameToId={};
    cats.forEach(c=>{ catNameToId[(c.name||'').toUpperCase()] = c.id; });
    allProds=allProds.map(p=>{
      if(!p.catId && p.categoria){
        const mapped = catNameToId[(p.categoria||'').toUpperCase()];
        if(mapped) return {...p, catId: mapped};
      }
      return p;
    });
  }
  const cfg=getConfig();
  // v140: solo dígitos. El número va tal cual dentro de un href del catálogo
  // público (mismo dominio que el panel del admin): cualquier otra cosa era una
  // puerta para meter código en esa página.
  const waPhone=String(cfg.catalogPhone||cfg.adminPhone||'').replace(/\D/g,'');
  const catColors=['#006d8a','#7c3aed','#dc2626','#059669','#d97706','#2563eb','#be185d','#475569'];
  const dateStr=new Date().toLocaleDateString('es-ES',{year:'numeric',month:'long',day:'numeric'});
  // v80: identidad del negocio (🎨 Diseño del admin). Sin nada configurado
  // sale el AXONTECH de siempre y el teal original — nadie nota la diferencia.
  const _mDoc=getMarca();
  const _mNombre=escapeHTML(_marcaNombre(_mDoc));
  const _mBase=_marcaBase(_mDoc)||'#006d8a';
  const _mc=_maDerivarColores(_mBase)||_maDerivarColores('#006d8a');
  const _mLogo=(_mDoc&&_mDoc.logo)?_mDoc.logo:'';
  const _mEmoji=(_mDoc&&_mDoc.logoEmoji)?_mDoc.logoEmoji:'';
  let catCardsJS='';
  if(cats.length){
    let ci=0;
    cats.forEach(cat=>{
      const prods=allProds.filter(p=>p.catId===cat.id);
      if(!prods.length)return;
      const color=catColors[ci%catColors.length];ci++;
      prods.forEach(p=>{catCardsJS+=buildCatalogCardJS(p,cat,color,waPhone);});
    });
    const noCat=allProds.filter(p=>!p.catId||!cats.find(c=>c.id===p.catId));
    if(noCat.length){
      const color=catColors[ci%catColors.length];ci++;
      noCat.forEach(p=>{catCardsJS+=buildCatalogCardJS(p,null,color,waPhone);});
    }
  } else {
    allProds.forEach(p=>{catCardsJS+=buildCatalogCardJS(p,null,'#006d8a',waPhone);});
  }
  return `<!DOCTYPE html><html lang="es"><head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1">
<title>${_mNombre} - Catalogo</title>
<link rel="icon" href="iconos/favicon-96.png">
<meta property="og:title" content="${_mNombre} - Catalogo de Productos">
<meta property="og:description" content="Explora nuestros productos disponibles">
<meta property="og:type" content="website">
<meta name="theme-color" content="${_mBase}">
<style>
*{box-sizing:border-box;margin:0;padding:0;}
:root{--primary:${_mBase};--primary-dk:${_mc.dk};--accent:${_mc.accent};--bg:#f0f4f8;--card:#fff;--text:#1a1a2e;--muted:#64748b;--radius:16px;--shadow:0 4px 20px rgba(0,0,0,.08);}
.hero-logo-img{width:96px;height:96px;border-radius:26px;object-fit:cover;display:block;margin:0 auto 12px;box-shadow:0 4px 18px rgba(0,0,0,.25);border:2px solid rgba(255,255,255,.35);}
body{font-family:'Segoe UI',-apple-system,BlinkMacSystemFont,system-ui,sans-serif;background:var(--bg);color:var(--text);line-height:1.5;min-height:100vh;-webkit-font-smoothing:antialiased;}
.hero{background:linear-gradient(135deg,var(--primary-dk) 0%,var(--primary) 50%,var(--accent) 100%);padding:48px 20px 36px;text-align:center;position:relative;overflow:hidden;}
.hero::before{content:'';position:absolute;top:-50%;left:-50%;width:200%;height:200%;background:radial-gradient(circle,rgba(255,255,255,.06) 0%,transparent 60%);animation:heroGlow 8s ease-in-out infinite alternate;}
@keyframes heroGlow{0%{transform:rotate(0deg)}100%{transform:rotate(360deg)}}
.hero-logo{font-size:48px;font-weight:900;color:#fff;letter-spacing:10px;text-shadow:0 2px 20px rgba(0,0,0,.3);position:relative;z-index:1;}
.hero-logo.emoji{letter-spacing:0;text-shadow:none;font-size:64px;line-height:1;}
.hero-sub{font-size:14px;letter-spacing:5px;color:rgba(255,255,255,.8);font-weight:300;margin-top:4px;position:relative;z-index:1;}
.hero-line{width:50px;height:3px;background:rgba(255,255,255,.4);margin:14px auto;border-radius:2px;position:relative;z-index:1;}
.hero-info{font-size:11px;color:rgba(255,255,255,.55);letter-spacing:1px;position:relative;z-index:1;}
.hero-count{display:inline-block;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.2);border-radius:20px;padding:5px 18px;font-size:12px;color:rgba(255,255,255,.9);margin-top:12px;font-weight:600;position:relative;z-index:1;}
.nav{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.92);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-bottom:1px solid rgba(0,0,0,.06);padding:10px 16px;display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch;}
.nav::-webkit-scrollbar{display:none;}
.nav-btn{padding:7px 16px;border-radius:20px;border:1.5px solid #e2e8f0;background:#fff;font-size:12px;font-weight:700;color:var(--muted);cursor:pointer;white-space:nowrap;transition:all .2s;}
.nav-btn:hover{border-color:var(--primary);color:var(--primary);}
.nav-btn.active{background:var(--primary);color:#fff;border-color:var(--primary);box-shadow:0 2px 8px rgba(${_mc.rgbBase},.25);}
.container{max-width:1200px;margin:0 auto;padding:16px;}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:20px;}
.card{background:var(--card);border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow);transition:transform .25s,box-shadow .25s;position:relative;display:flex;flex-direction:column;}
.card:hover{transform:translateY(-4px);box-shadow:0 8px 30px rgba(0,0,0,.12);}
.card-img{height:220px;background:linear-gradient(145deg,#f8fafc,#eef2f7);display:flex;align-items:center;justify-content:center;overflow:hidden;position:relative;}
.card-img img{width:100%;height:100%;object-fit:cover;transition:transform .4s;}
.card:hover .card-img img{transform:scale(1.05);}
.card-img .no-img{font-size:64px;opacity:.25;}
.card-cat{position:absolute;top:12px;left:12px;color:#fff;padding:4px 12px;border-radius:8px;font-size:10px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;box-shadow:0 2px 6px rgba(0,0,0,.15);}
.card-body{padding:18px 20px 20px;flex:1;display:flex;flex-direction:column;}
.card-name{font-weight:800;font-size:16px;color:var(--text);margin-bottom:6px;line-height:1.3;min-height:42px;}
.card-desc{font-size:12.5px;color:var(--muted);line-height:1.55;margin-bottom:12px;height:58px;overflow:hidden;position:relative;cursor:pointer;transition:max-height .3s ease;}
.card-desc.expanded{max-height:500px;}
.card-desc-fade{position:absolute;bottom:0;left:0;right:0;height:28px;background:linear-gradient(transparent,#fff);pointer-events:none;transition:opacity .3s;}
.card-desc.expanded+.card-desc-fade,.card-desc.expanded~.card-desc-fade{opacity:0;}
.card-price{font-weight:900;font-size:22px;color:var(--primary);margin-bottom:12px;letter-spacing:.3px;min-height:30px;}
.card-badges{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px;min-height:26px;}
.badge{padding:4px 10px;border-radius:8px;font-size:10px;font-weight:700;letter-spacing:.3px;}
.badge-garantia{background:#f0fdf4;color:#16a34a;border:1px solid #bbf7d0;}
.wa-btn{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;padding:12px;border:none;border-radius:12px;background:linear-gradient(135deg,#25d366,#128c7e);color:#fff;font-size:13px;font-weight:700;cursor:pointer;transition:all .2s;text-decoration:none;letter-spacing:.3px;margin-top:auto;}
.wa-btn:hover{transform:scale(1.02);box-shadow:0 4px 14px rgba(37,211,102,.35);}
.wa-btn:active{transform:scale(.98);}
.wa-icon{font-size:18px;}
.footer{text-align:center;padding:32px 20px;margin-top:40px;border-top:1px solid #e2e8f0;background:#fff;}
.footer-brand{font-size:14px;font-weight:900;color:var(--primary);letter-spacing:4px;margin-bottom:6px;}
.footer-addr{font-size:11px;color:var(--muted);line-height:1.6;}
.footer-gen{font-size:9px;color:#cbd5e1;margin-top:8px;}
.float-wa{position:fixed;bottom:24px;right:24px;width:56px;height:56px;border-radius:50%;background:#25d366;color:#fff;display:flex;align-items:center;justify-content:center;font-size:28px;box-shadow:0 4px 16px rgba(37,211,102,.4);cursor:pointer;z-index:999;transition:transform .2s;text-decoration:none;border:none;}
.float-wa:hover{transform:scale(1.1);}
.empty{text-align:center;padding:60px 20px;color:var(--muted);}
.empty-icon{font-size:48px;margin-bottom:12px;opacity:.5;}
.pmodal-bg{position:fixed;inset:0;z-index:2000;background:rgba(0,0,0,.55);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:16px;opacity:0;transition:opacity .25s;pointer-events:none;}
.pmodal-bg.show{opacity:1;pointer-events:auto;}
.pmodal{background:var(--card);border-radius:var(--radius);max-width:420px;width:100%;max-height:90vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,.3);transform:translateY(20px);transition:transform .25s;}
.pmodal-bg.show .pmodal{transform:translateY(0);}
.pmodal-img{width:100%;height:260px;object-fit:cover;display:block;}
.pmodal-noimg{width:100%;height:180px;display:flex;align-items:center;justify-content:center;font-size:64px;opacity:.2;background:linear-gradient(145deg,#f8fafc,#eef2f7);}
.pmodal-cat{display:inline-block;color:#fff;padding:4px 12px;border-radius:8px;font-size:10px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;margin-bottom:8px;}
.pmodal-body{padding:20px 22px 24px;}
.pmodal-name{font-weight:800;font-size:20px;color:var(--text);margin-bottom:8px;line-height:1.3;}
.pmodal-desc{font-size:13.5px;color:var(--muted);line-height:1.65;margin-bottom:14px;}
.pmodal-price{font-weight:900;font-size:24px;color:var(--primary);margin-bottom:10px;}
.pmodal-badge{display:inline-block;padding:4px 12px;border-radius:8px;font-size:11px;font-weight:700;background:#f0fdf4;color:#16a34a;border:1px solid #bbf7d0;margin-bottom:16px;}
.pmodal-close{position:absolute;top:12px;right:12px;width:36px;height:36px;border-radius:50%;background:rgba(0,0,0,.45);color:#fff;border:none;font-size:18px;cursor:pointer;display:flex;align-items:center;justify-content:center;z-index:5;transition:background .2s;}
.pmodal-close:hover{background:rgba(0,0,0,.7);}
@media(max-width:640px){
  .hero{padding:36px 16px 28px;}
  .hero-logo{font-size:36px;letter-spacing:6px;}
  .hero-sub{font-size:11px;letter-spacing:3px;}
  .grid{grid-template-columns:1fr;gap:16px;}
  .card-img{height:200px;}
  .container{padding:12px;}
}
@media(min-width:641px) and (max-width:1024px){
  .grid{grid-template-columns:repeat(2,1fr);}
}
</style>
</head><body>
<div class="hero">
  ${_mLogo?`<img class="hero-logo-img" src="${_mLogo}" alt="">`:(_mEmoji?`<div class="hero-logo emoji">${escapeHTML(_mEmoji)}</div>`:`<div class="hero-logo">${_mNombre}</div>`)}
  <div class="hero-sub">CATALOGO DE PRODUCTOS</div>
  <div class="hero-line"></div>
  <div class="hero-info">${dateStr}</div>
  <div class="hero-count">${allProds.length} productos disponibles</div>
</div>
<div class="nav" id="catNav"></div>
<div class="container"><div class="grid" id="productGrid"></div></div>
<div class="pmodal-bg" id="pmodalBg" onclick="if(event.target===this)closeProduct()">
  <div class="pmodal" style="position:relative;">
    <button class="pmodal-close" onclick="closeProduct()">&times;</button>
    <div id="pmodalContent"></div>
  </div>
</div>
<div class="footer">
  <div class="footer-brand">${_mNombre}</div>
  ${TIENDA_DIRECCION ? `<div class="footer-addr">${escapeHTML(TIENDA_DIRECCION)}</div>` : ''}
  <div class="footer-gen">Catalogo actualizado: ${dateStr}</div>
</div>
${waPhone?`<a class="float-wa" href="https://wa.me/${waPhone}?text=${encodeURIComponent('Hola, vi el catalogo de '+_marcaNombre(_mDoc)+' y me interesa...')}" target="_blank" title="Chat por WhatsApp">&#128172;</a>`:''}
<script>
var products=[${catCardsJS}];
var catNames=[${cats.map((c,i)=>"{id:"+c.id+",name:"+JSON.stringify(c.name)+",color:'"+catColors[i%catColors.length]+"'}").join(',')}${cats.length?'':",{id:0,name:'Todos',color:'#006d8a'}"}];
var activeCat=null;
function escapeHTML(s){if(s===null||s===undefined)return '';return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');}
function renderNav(){
  var n=document.getElementById('catNav');
  var h='<button class="nav-btn active" onclick="filterCat(null,this)">Todos</button>';
  catNames.forEach(function(c){
    var count=products.filter(function(p){return p.catId===c.id}).length;
    if(count) h+='<button class="nav-btn" onclick="filterCat('+c.id+',this)">'+escapeHTML(c.name)+' ('+count+')</button>';
  });
  n.innerHTML=h;
}
function filterCat(id,btn){
  activeCat=id;
  document.querySelectorAll('.nav-btn').forEach(function(b){b.classList.remove('active')});
  if(btn)btn.classList.add('active');
  renderGrid();
}
var PHOTO_RE=/^(https?:|data:image|photos\\.|.\\/photos\\.)/i;
function renderGrid(){
  var g=document.getElementById('productGrid');
  var filtered=activeCat!==null?products.filter(function(p){return p.catId===activeCat}):products;
  if(!filtered.length){g.innerHTML='<div class="empty"><div class="empty-icon">&#128230;</div><div>No hay productos en esta categoria</div></div>';return;}
  g.innerHTML=filtered.map(function(p){
    var s='<div class="card" onclick="openProduct('+p.id+')" style="cursor:pointer;">';
    s+='<div class="card-img">';
    // Validate photo URL — only allow http(s) and data URIs
    if(p.photo && PHOTO_RE.test(p.photo)){s+='<img src="'+escapeHTML(p.photo)+'" data-img="1" loading="lazy">';}
    s+='<div class="no-img" style="'+(p.photo?'display:none':'')+'">&#128230;</div>';
    if(p.catName){s+='<div class="card-cat" style="background:'+escapeHTML(p.catColor)+'">'+escapeHTML(p.catName)+'</div>';}
    s+='</div><div class="card-body">';
    s+='<div class="card-name">'+escapeHTML(p.name)+'</div>';
    s+='<div class="card-desc">'+escapeHTML(p.desc||'')+'<div class="card-desc-fade"></div></div>';
    s+='<div class="card-price">'+escapeHTML(p.price||'')+'</div>';
    s+='<div class="card-badges">';
    if(p.garantia){s+='<span class="badge badge-garantia">Garantia: '+escapeHTML(p.garantia)+'</span>';}
    s+='</div>';
    if(p.waLink){s+='<a class="wa-btn" href="'+escapeHTML(p.waLink)+'" target="_blank" onclick="event.stopPropagation();"><span class="wa-icon">&#128172;</span>Pedir por WhatsApp</a>';}
    // FIX: sin número de WhatsApp configurado la tarjeta no muestra nada.
    // Antes ponía una placa gris "No disponible" que confundía: el producto
    // SÍ está disponible, solo falta el número en ⚙️ Config → Teléfonos.
    s+='</div></div>';
    return s;
  }).join('');
}
function openProduct(id){
  var p=products.find(function(x){return x.id===id});if(!p)return;
  var c=document.getElementById('pmodalContent');
  var h='';
  if(p.photo && PHOTO_RE.test(p.photo)){h+='<img class="pmodal-img" src="'+escapeHTML(p.photo)+'" data-img="1"><div class="pmodal-noimg" style="display:none">&#128230;</div>';}
  else{h+='<div class="pmodal-noimg">&#128230;</div>';}
  h+='<div class="pmodal-body">';
  if(p.catName){h+='<div class="pmodal-cat" style="background:'+escapeHTML(p.catColor)+'">'+escapeHTML(p.catName)+'</div>';}
  h+='<div class="pmodal-name">'+escapeHTML(p.name)+'</div>';
  if(p.desc){h+='<div class="pmodal-desc">'+escapeHTML(p.desc)+'</div>';}
  if(p.price){h+='<div class="pmodal-price">'+escapeHTML(p.price)+'</div>';}
  if(p.garantia){h+='<div class="pmodal-badge">Garantia: '+escapeHTML(p.garantia)+'</div>';}
  if(p.waLink){h+='<a class="wa-btn" href="'+escapeHTML(p.waLink)+'" target="_blank"><span class="wa-icon">&#128172;</span>Pedir por WhatsApp</a>';}
  h+='</div>';
  c.innerHTML=h;
  document.getElementById('pmodalBg').classList.add('show');
}
function closeProduct(){document.getElementById('pmodalBg').classList.remove('show');}
document.addEventListener('error',function(e){var t=e.target;if(t.tagName==='IMG'&&t.dataset.img){t.style.display='none';if(t.nextElementSibling)t.nextElementSibling.style.display='flex';}},true);
renderNav();renderGrid();
</script>
</body></html>`;
}

