// ══════════════════════════════════════════
//  AUTH & SOUND
// ══════════════════════════════════════════
// NOTA: checkPass() fue eliminada — era código muerto (no se llamaba desde ningún
// sitio, el login usa verifyPassAsync) y contenía un fallback inseguro basado en
// sessionStorage manipulable. Ver AUDITORIA-AXONTECH.md MEDIO 19.

// Async password verification — use this for login forms
async function verifyPassAsync(input) {
  const stored = localStorage.getItem('axon_admin_hash');
  if (!stored) {
    // Default password
    const defaultHash = await _hashPass('axon2024');
    if (input === 'axon2024') {
      localStorage.setItem('axon_admin_hash', defaultHash);
      return true;
    }
    return false;
  }
  if (stored.startsWith('sha256:')) {
    // Migration path: try legacy v74 hash (SHA-256 with static salt) FIRST.
    // This must run BEFORE _hashPass() because _hashPass generates a random salt
    // on first call, and we need to detect the legacy format independently of
    // whether a salt exists yet.
    try {
      const legacyData = new TextEncoder().encode(input + '_axontech_salt_2024');
      const legacyBuf = await crypto.subtle.digest('SHA-256', legacyData);
      const legacyArr = Array.from(new Uint8Array(legacyBuf));
      const legacyHash = 'sha256:' + legacyArr.map(b => b.toString(16).padStart(2, '0')).join('');
      if (legacyHash === stored) {
        // Legacy v74 hash matched — migrate to new PBKDF2 format.
        const newHash = await _hashPass(input);
        localStorage.setItem('axon_admin_hash', newHash);
        sessionStorage.setItem('axon_admin_session', newHash);
        return true;
      }
    } catch(e) {}
    // Try the new PBKDF2 hash (for v75+ hashes that already have a salt)
    const inputHash = await _hashPass(input);
    if (inputHash === stored) {
      sessionStorage.setItem('axon_admin_session', stored);
      return true;
    }
    return false;
  }
  // Legacy btoa migration (very old versions stored btoa(password))
  if (btoa(input) === stored) {
    const h = await _hashPass(input);
    localStorage.setItem('axon_admin_hash', h);
    localStorage.removeItem('axon_admin_hash_legacy');
    sessionStorage.setItem('axon_admin_session', h);
    return true;
  }
  return false;
}
async function _hashPass(input) {
  // PBKDF2-style hashing: per-user random salt + 100k iterations of SHA-256.
  // Falls back to legacy SHA-256 + static salt if WebCrypto PBKDF2 is unavailable.
  try {
    const saltB64 = localStorage.getItem('axon_admin_salt');
    let salt;
    if (saltB64) {
      // Reuse existing salt
      const bin = atob(saltB64);
      salt = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) salt[i] = bin.charCodeAt(i);
    } else {
      // Generate a new 16-byte salt
      salt = crypto.getRandomValues(new Uint8Array(16));
      let bin = '';
      salt.forEach(b => bin += String.fromCharCode(b));
      localStorage.setItem('axon_admin_salt', btoa(bin));
    }
    const keyMaterial = await crypto.subtle.importKey(
      'raw', new TextEncoder().encode(input), 'PBKDF2', false, ['deriveBits']
    );
    const hashBuf = await crypto.subtle.deriveBits(
      { name: 'PBKDF2', salt, iterations: 100000, hash: 'SHA-256' },
      keyMaterial, 256
    );
    const hashArr = Array.from(new Uint8Array(hashBuf));
    return 'sha256:' + hashArr.map(b => b.toString(16).padStart(2, '0')).join('');
  } catch(e) {
    // Fallback: simple SHA-256 with static salt (less secure, but functional)
    const data = new TextEncoder().encode(input + '_axontech_salt_2024');
    const hashBuffer = await crypto.subtle.digest('SHA-256', data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return 'sha256:' + hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
  }
}
// Timing-safe string comparison to prevent timing attacks on hashes
function _timingSafeEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}
// ── v42: Gestor passwords HASHEADAS (PBKDF2) — ya no se guardan en texto plano.
// Formato: 'pbkdf2$100000$<salt b64>$<hex>' · fallback legacy: 'sha256:<hex>'
// El admin NO puede ver la clave una vez hasheada — usa "↺ Resetear" para
// generar una nueva (gestiones en resetGestorPass/addGestor).
async function _hashGestorPass(input) {
  try {
    const salt = crypto.getRandomValues(new Uint8Array(16));
    const keyMaterial = await crypto.subtle.importKey(
      'raw', new TextEncoder().encode(input), 'PBKDF2', false, ['deriveBits']
    );
    const hashBuf = await crypto.subtle.deriveBits(
      { name: 'PBKDF2', salt, iterations: 100000, hash: 'SHA-256' },
      keyMaterial, 256
    );
    let bin = '';
    salt.forEach(b => bin += String.fromCharCode(b));
    const hashArr = Array.from(new Uint8Array(hashBuf));
    return 'pbkdf2$100000$' + btoa(bin) + '$' + hashArr.map(b => b.toString(16).padStart(2, '0')).join('');
  } catch(e) {
    const data = new TextEncoder().encode(input + '_axontech_salt_2024');
    const hashBuffer = await crypto.subtle.digest('SHA-256', data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return 'sha256:' + hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
  }
}
// ── v133: encriptar las claves que siguen en texto plano ────────────────────
// Las claves se encriptan desde v42, pero las de antes solo se migraban cuando
// ese gestor volvía a entrar. En los datos reales quedaban 26 sin encriptar, y
// la tabla de gestores se puede leer con la clave pública que va dentro de la
// app. El teléfono del admin las encripta él mismo, en segundo plano: la
// comparación de las claves viejas ya era en mayúsculas, así que se encripta
// la clave en mayúsculas y cada gestor sigue entrando con la suya de siempre.
let _encriptandoClaves = false, _encriptadoTimer = null;
function _programarEncriptadoClavesViejas() {
  if (typeof IS_ADMIN === 'undefined' || !IS_ADMIN) return;
  clearTimeout(_encriptadoTimer);
  // Se espera a que haya bajado la lista de gestores de la nube; y se repite de
  // vez en cuando por si llega alguno importado de un respaldo viejo.
  _encriptadoTimer = setTimeout(() => { try { repararTotalesVacios(); } catch(e) {}   // v134
    encriptarClavesViejas().finally(() => {
    _encriptadoTimer = setTimeout(_programarEncriptadoClavesViejas, 10 * 60 * 1000); }); }, 15000);
}
// ── v134: vales con el total vacío ─────────────────────────────────────────
// Sin total no hay "COBRAR AL CLIENTE", ni forma de pago, ni entra en la caja
// (en los datos reales, V-150: precio $150 USD y total vacío). Desde v133 no se
// puede guardar así; los que ya estaban se rellenan con sus precios.
function repararTotalesVacios() {
  if (typeof IS_ADMIN === 'undefined' || !IS_ADMIN) return 0;
  let n = 0;
  getVales().forEach(v => {
    if (!v || v.status === 'cancelled' || String(v.total || '').trim()) return;
    const t = _totalDesdePrecios(v.precioUSD, v.precioMN, v.mensajeria);
    if (t) { patchVale(v.id, { total: t }); n++; }
  });
  if (n) _logAudit('totales_reparados', n + ' vales');
  return n;
}
// ── v138: el admin puede VER las claves de los gestores ────────────────────
// Pedido: "que las contraseñas de los gestores en el admin no salgan
// encriptadas". El hash (PBKDF2) no se puede deshacer —es de una sola
// dirección—, así que además del hash se guarda una copia LEGIBLE SOLO PARA EL
// ADMIN:
//   · Hay una llave doble (RSA). La parte pública va en el config, que ven
//     todos: con ella cualquier teléfono puede CERRAR un sobre con una clave.
//   · La parte privada, la que ABRE los sobres, se guarda en la nube cifrada
//     con la contraseña del admin (documento claves_admin, que los gestores no
//     bajan). Solo se abre en el teléfono del admin al entrar con su clave.
//   · Cada gestor lleva su sobre (claveVisible). Lo cierra el admin al crear o
//     resetear una clave, y el propio teléfono del gestor al entrar con la suya
//     —así las claves que ya estaban encriptadas aparecen solas, sin cambiarle
//     la clave a nadie.
// Quien tenga la dirección de la base de datos ve sobres cerrados, no claves.
// Por eso importa que la contraseña del admin NO sea la de fábrica.
let _llavePrivada = null;
let _llaveEstado = '';           // '' | 'abierta' | 'otra_clave' | 'sin_red'
let _llaveReintentos = 0;
function _aB64(buf) { const u = new Uint8Array(buf); let t = ''; for (let i = 0; i < u.length; i += 0x8000) t += String.fromCharCode.apply(null, u.subarray(i, i + 0x8000)); return btoa(t); }
const _deB64 = s => Uint8Array.from(atob(String(s || '')), c => c.charCodeAt(0));
const _RSA = { name: 'RSA-OAEP', hash: 'SHA-256' };
const _etiquetaClave = hash => String(hash || '').slice(-16);
const _clavePublicaTxt = () => String((getConfig() || {}).clavesPub || '');
async function _llaveDeClaveAdmin(pass, sal) {
  const base = await crypto.subtle.importKey('raw', new TextEncoder().encode(String(pass)), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey({ name: 'PBKDF2', salt: sal, iterations: 200000, hash: 'SHA-256' }, base,
    { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
}
async function _envolverPrivada(pkcs8, pass, pub) {
  const sal = crypto.getRandomValues(new Uint8Array(16)), iv = crypto.getRandomValues(new Uint8Array(12));
  const k = await _llaveDeClaveAdmin(pass, sal);
  const ct = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, k, pkcs8);
  return { v: 1, sal: _aB64(sal), iv: _aB64(iv), priv: _aB64(ct), pub };
}
async function _leerMetaDeLaNube(name) {
  const res = await fetch(`${_GS_REST}/meta?select=data&name=eq.${encodeURIComponent(name)}`, { headers: _GS_HDRS });
  if (!res.ok) throw new Error('meta ' + res.status);
  const rows = await res.json();
  return (rows && rows[0]) ? rows[0].data : null;
}
// v140: la llave pública se "fija" la primera vez que este teléfono la ve. Si
// después aparece otra en el config, NO se usa: cualquiera con la dirección de
// la base de datos podía cambiarla por la suya y recibir las claves nuevas.
const _PUB_FIJADA_KEY = 'axon_claves_pub_fijada';
function _pubFijada() { try { return localStorage.getItem(_PUB_FIJADA_KEY) || ''; } catch(e) { return ''; } }
function _fijarPub(pub) { try { if (pub) localStorage.setItem(_PUB_FIJADA_KEY, pub); } catch(e) {} }
let _clavesClaras = new Map();   // id gestor → clave, solo en memoria del admin con la llave abierta
async function _cifrarParaAdmin(texto) {
  const pub = _clavePublicaTxt();
  if (!pub || !window.crypto || !crypto.subtle) return null;
  const fijada = _pubFijada();
  if (!fijada) _fijarPub(pub);
  else if (fijada !== pub) { console.warn('[claves] la llave pública del config no es la de siempre — no se usa'); return null; }
  try {
    const k = await crypto.subtle.importKey('spki', _deB64(pub), _RSA, false, ['encrypt']);
    return _aB64(await crypto.subtle.encrypt({ name: 'RSA-OAEP' }, k, new TextEncoder().encode(String(texto))));
  } catch (e) { return null; }
}
async function _leerClaveGestor(g) {
  if (!_llavePrivada || !g || !g.claveVisible || g.claveVisibleDe !== _etiquetaClave(g.password)) return null;
  try { return new TextDecoder().decode(await crypto.subtle.decrypt({ name: 'RSA-OAEP' }, _llavePrivada, _deB64(g.claveVisible))); }
  catch (e) { return null; }
}
// Se llama al entrar el admin, con la contraseña que acaba de escribir (solo
// vive en memoria, y solo mientras se reintenta).
async function _abrirLlavero(passAdmin) {
  if (typeof IS_ADMIN === 'undefined' || !IS_ADMIN || !window.crypto || !crypto.subtle) return false;
  let doc;
  try { doc = await _leerMetaDeLaNube('claves_admin'); }
  catch (e) {                                   // sin red: se reintenta un rato
    _llaveEstado = 'sin_red';
    if (_llaveReintentos++ < 24) setTimeout(() => _abrirLlavero(passAdmin), 5000);
    return false;
  }
  try {
    if (!doc || !doc.priv) {
      // v140: con la contraseña de fábrica (sale en el código público) no se
      // crea: cualquiera podría abrir la llave.
      if (String(passAdmin) === 'axon2024') {
        _llaveEstado = 'clave_fabrica'; _pintarClavesGestores();
        showToast('🔑 Para poder ver las claves de los gestores, cambia antes la contraseña del admin (Config)');
        return false;
      }
      // No existe en la nube: es la primera vez. Se crea la llave doble.
      const par = await crypto.subtle.generateKey({ ..._RSA, modulusLength: 2048, publicExponent: new Uint8Array([1, 0, 1]) },
                                                   true, ['encrypt', 'decrypt']);
      const pub = _aB64(await crypto.subtle.exportKey('spki', par.publicKey));
      doc = await _envolverPrivada(await crypto.subtle.exportKey('pkcs8', par.privateKey), passAdmin, pub);
      _safeSetLS('axon_claves_admin', JSON.stringify(doc));
      setSB('claves_admin', doc);
      _logAudit('llavero_creado', 'claves de gestores legibles para el admin');
      // v140: si otro equipo de admin la creó a la vez, se queda la de la nube.
      setTimeout(async () => {
        try {
          const nube = await _leerMetaDeLaNube('claves_admin');
          if (nube && nube.pub && nube.pub !== doc.pub) { _llavePrivada = null; await _abrirLlavero(passAdmin); }
        } catch(e) {}
      }, 4000);
    }
    const k = await _llaveDeClaveAdmin(passAdmin, _deB64(doc.sal));
    let pkcs8;
    try { pkcs8 = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: _deB64(doc.iv) }, k, _deB64(doc.priv)); }
    catch (e) { _llaveEstado = 'otra_clave'; _pintarClavesGestores(); return false; }
    _llavePrivada = await crypto.subtle.importKey('pkcs8', pkcs8, _RSA, true, ['decrypt']);
    _llaveEstado = 'abierta';
    if (doc.pub) _fijarPub(doc.pub);   // v140: la que abre el admin es la buena
    if (String(passAdmin) === 'axon2024') showToast('⚠️ La llave de las claves está cerrada con la contraseña de fábrica: cambia la contraseña del admin en Config');
    _clavesClaras = new Map();
    for (const g of getGestores()) { const c = await _leerClaveGestor(g); if (c) _clavesClaras.set(String(g.id), c); }
    _safeSetLS('axon_claves_admin', JSON.stringify(doc));
    // La pública del config es la que usan los gestores: si alguien la pisó
    // con un config viejo, se repone desde el documento.
    if (doc.pub && _clavePublicaTxt() !== doc.pub) saveConfig({ ...(getConfig() || {}), clavesPub: doc.pub });
    _programarEncriptadoClavesViejas();   // las que sigan en texto plano, ya con su sobre
    _pintarClavesGestores();
    return true;
  } catch (e) { console.warn('[llavero]', e && e.message); return false; }
}
// Al cambiar la contraseña del admin, la llave se vuelve a cerrar con la nueva.
async function _recerrarLlavero(passNueva) {
  if (!_llavePrivada) return false;
  try {
    const doc = JSON.parse(localStorage.getItem('axon_claves_admin') || 'null');
    const nuevo = await _envolverPrivada(await crypto.subtle.exportKey('pkcs8', _llavePrivada), passNueva, doc && doc.pub);
    _safeSetLS('axon_claves_admin', JSON.stringify(nuevo));
    setSB('claves_admin', nuevo);
    return true;
  } catch (e) { return false; }
}
// El teléfono del GESTOR, al entrar con su clave correcta, cierra su sobre si
// no lo tiene (o si es de una clave anterior). No cambia la clave.
async function _mandarClaveAlAdmin(id, clave) {
  try {
    if (typeof IS_ADMIN !== 'undefined' && IS_ADMIN) return;
    const g = gestorOf(id);
    if (!g || !g.password || !_clavePublicaTxt()) return;
    const pw = String(g.password);
    if (!pw.startsWith('pbkdf2$') && !pw.startsWith('sha256:')) return;   // se encripta primero; entra la próxima vez
    const tag = _etiquetaClave(pw);
    if (g.claveVisible && g.claveVisibleDe === tag) return;
    const ct = await _cifrarParaAdmin(String(clave).trim().toUpperCase());
    if (!ct) return;
    // v140: se parte de la ficha que hay en la NUBE, no de la copia de este
    // teléfono (puede tener horas): subirla entera deshacía, por ejemplo, un
    // reseteo de clave recién hecho por el admin.
    let nube = null;
    try {
      const res = await fetch(`${_GS_REST}/gestores?select=data&id=eq.${encodeURIComponent(String(g.id))}`, { headers: _GS_HDRS });
      if (res.ok) { const rows = await res.json(); nube = rows && rows[0] && rows[0].data; }
    } catch(e) {}
    if (!nube || nube.password !== pw) return;            // sin red o la clave ya cambió: nada
    const list = getGestores().slice();
    const i = list.findIndex(x => String(x.id) === String(id));
    if (i === -1) return;
    list[i] = { ...nube, claveVisible: ct, claveVisibleDe: tag };
    guardarGestores(list, [list[i].id]);
  } catch (e) {}
}
// Pinta el texto de cada clave en la lista del admin.
function _htmlClaveGestor(g) {
  const pw = String(g && g.password || '');
  const hashed = pw.startsWith('pbkdf2$') || pw.startsWith('sha256:');
  if (!hashed) return '🔑 ' + escapeHTML(pw || '—').replace(/./g, '•');
  if (g.claveVisible && g.claveVisibleDe === _etiquetaClave(pw)) return _llavePrivada ? '🔑 ••••••' : '🔒 Encriptada';
  return '⏳ Se verá al entrar';
}
function _pintarClavesGestores() {
  getGestores().forEach(g => { const el = document.getElementById('gpw-' + g.id); if (el && el.dataset.shown !== '1') el.textContent = _htmlClaveGestor(g).replace(/&[^;]+;/g, '•'); });
}
async function encriptarClavesViejas() {
  if (_encriptandoClaves) return 0;
  const esPlana = pw => { const t = String(pw || '').trim(); return !!t && !t.startsWith('pbkdf2$') && !t.startsWith('sha256:'); };
  const pendientes = getGestores().filter(g => g && esPlana(g.password)).map(g => ({ id: g.id, plana: String(g.password).trim() }));
  if (!pendientes.length) return 0;
  // v140: se encriptan aunque aún no haya llave (la seguridad primero): si no
  // llevan sobre, el sobre lo cierra el teléfono del gestor la próxima vez que
  // entre (_mandarClaveAlAdmin), así que el admin no las pierde de vista.
  _encriptandoClaves = true;
  try {
    const hechos = [];
    for (const x of pendientes) {
      try {
        const hash = await _hashGestorPass(x.plana.toUpperCase());
        // v138: su sobre para el admin, con la misma clave — así no se pierde de vista.
        const sobre = await _cifrarParaAdmin(x.plana.toUpperCase());
        hechos.push({ id: x.id, plana: x.plana, hash, sobre });
      } catch(e) {}
    }
    // Se relee la lista AHORA (ver v129): solo se toca a quien siga teniendo la
    // misma clave en texto plano; si mientras tanto alguien la cambió, se respeta.
    const list = getGestores().slice();
    const ids = [];
    hechos.forEach(h => {
      const i = list.findIndex(g => g && g.id === h.id);
      if (i !== -1 && String(list[i].password || '').trim() === h.plana) {
        list[i] = { ...list[i], password: h.hash, ...(h.sobre ? { claveVisible: h.sobre, claveVisibleDe: _etiquetaClave(h.hash) } : {}) };
        ids.push(h.id);
      }
    });
    if (ids.length) { guardarGestores(list, ids); _logAudit('gestor_pass_encriptadas', ids.length + ' claves'); }
    return ids.length;
  } finally { _encriptandoClaves = false; }
}
async function _gestorPassMatches(input, stored) {
  const val = String(input || '').trim().toUpperCase();
  const sys = String(stored || '').trim();
  if (!sys) return false;
  if (sys.startsWith('pbkdf2$')) {
    try {
      const parts = sys.split('$');
      const iterations = parseInt(parts[1], 10) || 100000;
      const bin = atob(parts[2] || '');
      const salt = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) salt[i] = bin.charCodeAt(i);
      const keyMaterial = await crypto.subtle.importKey(
        'raw', new TextEncoder().encode(val), 'PBKDF2', false, ['deriveBits']
      );
      const hashBuf = await crypto.subtle.deriveBits(
        { name: 'PBKDF2', salt, iterations, hash: 'SHA-256' },
        keyMaterial, 256
      );
      const hashArr = Array.from(new Uint8Array(hashBuf));
      const hex = hashArr.map(b => b.toString(16).padStart(2, '0')).join('');
      return _timingSafeEqual(hex, parts[3] || '');
    } catch(e) { return false; }
  }
  if (sys.startsWith('sha256:')) {
    try {
      const data = new TextEncoder().encode(val + '_axontech_salt_2024');
      const hashBuffer = await crypto.subtle.digest('SHA-256', data);
      const hashArray = Array.from(new Uint8Array(hashBuffer));
      const hex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
      return _timingSafeEqual('sha256:' + hex, sys);
    } catch(e) { return false; }
  }
  // Legacy: texto plano (backward compat, se migra al hacer login)
  return _timingSafeEqual(val, sys.toUpperCase());
}
function changePass() {
  const np = document.getElementById('newPassInput').value.trim();
  if (!np||np.length<4){showToast('Mínimo 4 caracteres');return;}
  _hashPass(np).then(h => {
    localStorage.setItem('axon_admin_hash', h);
    // No longer storing reversible btoa version — security improvement
    localStorage.removeItem('axon_admin_hash_legacy');
    document.getElementById('newPassInput').value='';
    // v138: la llave de las claves de los gestores se vuelve a cerrar con la nueva.
    _recerrarLlavero(np).then(ok => showToast(ok || !_clavePublicaTxt() ? 'Contraseña actualizada ✓'
      : 'Contraseña actualizada ✓ — para ver las claves de los gestores entra con la anterior y cámbiala otra vez'));
  });
}
// Shared AudioContext to prevent memory leak from creating new contexts
let _sharedAC = null;
function playSound(type) {
  try {
    if (!_sharedAC) _sharedAC = new (window.AudioContext||window.webkitAudioContext)();
    const ac = _sharedAC;
    if (ac.state === 'suspended') ac.resume();
    const g=ac.createGain();g.connect(ac.destination);
    g.gain.setValueAtTime(0.08,ac.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001,ac.currentTime+0.8);
    const tones={login:[[880,0],[1100,.15]],vale:[[660,0],[800,.18]],confirm:[[440,0],[660,.15],[880,.3]]};
    (tones[type]||tones.login).forEach(t=>{const o=ac.createOscillator();o.type='sine';o.frequency.value=t[0];o.connect(g);o.start(ac.currentTime+t[1]);o.stop(ac.currentTime+t[1]+0.2);});
  } catch(e){}
}

