// ── Pintar la ayuda ────────────────────────────────────────────────────────
let _ayudaSeccion = null;   // null = todas
function limpiarBuscadorAyuda() {
  const i = document.getElementById('ayudaBuscador');
  if (i) { i.value = ''; i.focus(); }
  renderAyuda();
}
function ayudaFiltrar(id) {
  _ayudaSeccion = (_ayudaSeccion === id) ? null : id;
  renderAyuda();
}
function _ayudaCoincide(t, q) {
  if (!q) return true;
  const txt = [t.titulo, t.para, t.como, t.ojo, t.donde].filter(Boolean).join(' ').toLowerCase();
  // Todas las palabras, en cualquier orden: "puntos gestor" encuentra el tema
  // aunque en el texto vayan al revés.
  return q.split(/\s+/).filter(Boolean).every(w => txt.includes(w));
}
function renderAyuda() {
  const cont = document.getElementById('ayudaContenido');
  const chips = document.getElementById('ayudaChips');
  if (!cont) return;
  const inp = document.getElementById('ayudaBuscador');
  const q = ((inp && inp.value) || '').trim().toLowerCase();
  const btnLimpiar = document.getElementById('ayudaBuscadorLimpiar');
  if (btnLimpiar) btnLimpiar.style.display = q ? 'block' : 'none';

  // Al buscar se ignora la sección elegida, por lo mismo que en el buscador de
  // Stock: si escribes "merma" y no sale porque tenías puesto otro filtro, el
  // buscador parece roto.
  const secciones = AYUDA_SECCIONES
    .filter(s => q || !_ayudaSeccion || s.id === _ayudaSeccion)
    .map(s => ({ ...s, temas: s.temas.filter(t => _ayudaCoincide(t, q)) }))
    .filter(s => s.temas.length);

  if (chips) {
    chips.innerHTML = AYUDA_SECCIONES.map(s => {
      const on = !q && _ayudaSeccion === s.id;
      return `<button type="button" class="pcat-tab ${on ? 'active' : ''}" onclick="ayudaFiltrar('${s.id}')">${s.icono} ${escapeHTML(s.titulo)}</button>`;
    }).join('');
    chips.style.opacity = q ? '.45' : '1';
  }

  const total = AYUDA_SECCIONES.reduce((n, s) => n + s.temas.length, 0);
  const hallados = secciones.reduce((n, s) => n + s.temas.length, 0);

  if (!secciones.length) {
    cont.innerHTML = `<div class="es"><div class="es-icon">🔎</div><div class="es-text">Nada coincide con “${escapeHTML(q)}”.<br>
      <span style="font-size:11px;">Prueba con una palabra suelta: merma, puntos, rebaja, clave, unir…</span></div></div>`;
    return;
  }

  const tema = t => {
    const dib = t.dibujo && AYUDA_DIBUJOS[t.dibujo] ? AYUDA_DIBUJOS[t.dibujo]() : '';
    return `<div style="background:var(--surface);border:1px solid var(--border);border-radius:11px;padding:13px 15px;margin-bottom:8px;">
      <div style="display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin-bottom:3px;">
        <span style="font-size:16px;">${t.icono}</span>
        <span style="font-size:14px;font-weight:800;color:var(--text);">${escapeHTML(t.titulo)}</span>
        ${t.nuevo ? `<span style="background:linear-gradient(135deg,#10B981,#059669);color:#fff;border-radius:6px;padding:1px 6px;font-size:9px;font-weight:800;">NUEVO ${escapeHTML(t.nuevo)}</span>` : ''}
        ${t.donde ? `<span style="font-size:10px;color:var(--text-muted);">· ${escapeHTML(t.donde)}</span>` : ''}
      </div>
      <div style="font-size:12.5px;color:var(--text);line-height:1.5;margin-bottom:5px;">${escapeHTML(t.para)}</div>
      ${t.como ? `<div style="font-size:11.5px;color:var(--text-muted);line-height:1.5;"><b style="color:var(--text);">Cómo:</b> ${escapeHTML(t.como)}</div>` : ''}
      ${t.ojo ? `<div style="margin-top:7px;font-size:11px;line-height:1.5;background:rgba(245,158,11,.10);border-left:3px solid var(--orange);border-radius:6px;padding:7px 10px;color:var(--text);">⚠️ ${escapeHTML(t.ojo)}</div>` : ''}
      ${dib}
    </div>`;
  };

  cont.innerHTML =
    (q ? `<div style="font-size:11px;color:var(--text-muted);margin-bottom:8px;">${hallados} de ${total} · se buscó en todas las secciones</div>` : '')
    + secciones.map(s => `
      <div style="margin-bottom:16px;">
        <div class="lbl" style="margin-top:0;">${s.icono} ${escapeHTML(s.titulo)}</div>
        ${s.intro && !q ? `<div style="font-size:11.5px;color:var(--text-muted);margin:-4px 0 8px;line-height:1.5;">${escapeHTML(s.intro)}</div>` : ''}
        ${s.dibujo && !q && AYUDA_DIBUJOS[s.dibujo] ? `<div style="background:var(--surface);border:1px solid var(--border);border-radius:11px;padding:8px;margin-bottom:8px;">${AYUDA_DIBUJOS[s.dibujo]()}</div>` : ''}
        ${s.temas.map(tema).join('')}
      </div>`).join('');
}

// ══════════════════════════════════════════════════════════════════════════
//  AVISOS AL TELÉFONO DEL GESTOR SOBRE EL STOCK  (v120)
// ══════════════════════════════════════════════════════════════════════════
// El gestor tiene que enterarse de tres cosas sin abrir la app: que entró un
// producto nuevo, que se acabó uno (para no venderlo y quedar mal con el
// cliente) y que se repuso uno que estaba agotado.
//
// Esto NO es push de servidor: no hay servidor propio ni claves VAPID, y
// montarlo costaría dinero. Es la notificación del sistema que lanza el propio
// teléfono cuando la app —abierta o en segundo plano— recibe el aviso por el
// sondeo. En un móvil con la app instalada se ve igual que un push normal.
//
// Se dispara al BAJAR los avisos, no al crearlos: quien los crea es el admin en
// su teléfono; el gestor solo se entera cuando le llegan.
const _PUSH_TIPOS = {
  new_product:  { titulo: '💎 Producto nuevo',      accion: 'Ya se puede vender' },
  out_of_stock: { titulo: '❌ Producto agotado',    accion: 'No lo ofrezcas hasta que se reponga' },
  restocked:    { titulo: '📦 Producto repuesto',   accion: 'Vuelve a estar disponible' },
  // v132: precio, comisión, puntos, garantía o nombre. Se avisa igual que un
  // producto nuevo: el gestor tiene que saberlo ANTES de darle un precio al cliente.
  product_changed: { titulo: '✏️ Cambió un producto', accion: 'Revísalo antes de ofrecerlo' },
};
const _PUSH_VISTOS_KEY = 'axon_push_vistos';
// Solo se avisa de lo que pasó hace poco. Sin este freno, la primera vez que un
// teléfono se sincroniza se le echarían encima veinte notificaciones de cosas
// de la semana pasada.
const _PUSH_MAX_EDAD_MS = 6 * 60 * 60 * 1000;
function _pushYaVistos() {
  try { const a = JSON.parse(localStorage.getItem(_PUSH_VISTOS_KEY) || '[]'); return Array.isArray(a) ? a : []; }
  catch(e) { return []; }
}
function _pushApuntarVistos(ids) {
  try {
    // Se guardan los últimos 300 y no todos: la lista solo sirve para no repetir
    // un aviso reciente, y sin poda crecería para siempre en el teléfono.
    const nuevos = _pushYaVistos().concat(ids).slice(-300);
    localStorage.setItem(_PUSH_VISTOS_KEY, JSON.stringify(nuevos));
  } catch(e) {}
}
// La foto del producto, si la tiene, para que el aviso se reconozca de un
// vistazo. Si no hay, el icono de la app.
function _pushIconoProducto(pid) {
  try {
    const p = pid != null ? productoOf(pid) : null;
    if (p && p.photo && typeof _resolvePhotoUrl === 'function') {
      const u = _resolvePhotoUrl(p.photo);
      if (u) return u;
    }
  } catch(e) {}
  return './iconos/icon-192.png';
}
function _pushDeProductos(antes, despues) {
  // El admin no se avisa a sí mismo: él es quien acaba de hacer el cambio.
  if (typeof IS_ADMIN !== 'undefined' && IS_ADMIN) return 0;
  if (!('Notification' in window) || Notification.permission !== 'granted') return 0;
  if (!Array.isArray(despues)) return 0;
  const habia = new Set((Array.isArray(antes) ? antes : []).map(n => n && n.id).filter(x => x != null));
  const vistos = new Set(_pushYaVistos());
  const ahora = Date.now();
  const nuevos = [];
  despues.forEach(n => {
    if (!n || !_PUSH_TIPOS[n.type]) return;
    if (habia.has(n.id) || vistos.has(n.id)) return;        // ya estaba o ya se avisó
    const t = Date.parse(n.ts || '');
    if (!isFinite(t) || (ahora - t) > _PUSH_MAX_EDAD_MS) return;   // demasiado viejo
    nuevos.push(n);
  });
  if (!nuevos.length) return 0;
  // De más reciente a más antiguo, y como mucho tres: una ráfaga de avisos se
  // ignora igual que si no llegara ninguno.
  nuevos.sort((a, b) => Date.parse(b.ts || 0) - Date.parse(a.ts || 0));
  const _lanzar = nuevos.slice(0, 3);
  _lanzar.forEach(n => {
    const tipo = _PUSH_TIPOS[n.type];
    const nombre = String(n.productName || 'Producto');
    const extra = String(n.extra || '').trim();
    // El cuerpo dice el producto y qué hacer; el extra trae el stock que quedó
    // o el precio, según el aviso, y ayuda a decidir sin abrir la app.
    const cuerpo = nombre + (extra ? ' · ' + extra : '') + '\n' + tipo.accion;
    _pushConFoto(tipo.titulo, cuerpo, _pushIconoProducto(n.productId), 'stock:' + n.id);
  });
  _pushApuntarVistos(nuevos.map(n => n.id));
  return _lanzar.length;
}
// Como sendBrowserNotif pero con la foto del producto y una etiqueta, para que
// dos avisos del mismo producto no se apilen en la barra de notificaciones.
function _pushConFoto(titulo, cuerpo, icono, etiqueta) {
  if (!('Notification' in window) || Notification.permission !== 'granted') return;
  const opts = { body: cuerpo, icon: icono, badge: './iconos/icon-192.png', tag: etiqueta, renotify: true };
  try {
    if ('serviceWorker' in navigator && navigator.serviceWorker.ready) {
      navigator.serviceWorker.ready
        .then(reg => reg.showNotification(titulo, opts))
        .catch(() => { try { new Notification(titulo, opts); } catch(e) {} });
    } else {
      new Notification(titulo, opts);
    }
  } catch(e) { console.warn('[push] no se pudo avisar:', e && e.message); }
}

// ══════════════════════════════════════════
//  v78 — EXPERIENCIA APP
//  Haptics · check animado · confeti ligero · skeletons ·
//  tab bar inferior · hoja de perfil · alto contraste · header glass
//  Todo opt-in/progresivo: si algo no existe en el navegador, no pasa nada.
// ══════════════════════════════════════════

// Marca de arranque: mientras está en true, la lista vacía de gestores muestra
// skeletons en vez de "aún no hay gestores" (que era mentira durante el primer
// tirón a la nube). Se apaga sola por timeout de seguridad.
window.__axonBooting = true;
setTimeout(function(){ window.__axonBooting = false; }, 9000);

// ── Haptics (Android; iOS no expone vibrate y simplemente ignora) ──
function haptic(pattern){
  try{
    if(localStorage.getItem('axon_haptics') === 'off') return;
    if('vibrate' in navigator) navigator.vibrate(pattern || 10);
  }catch(e){}
}

// ── Check animado de éxito (pill flotante con SVG que se dibuja) ──
function _axSuccessSvg(){
  return '<svg viewBox="0 0 24 24" aria-hidden="true">'
    + '<circle class="axc-ring" cx="12" cy="12" r="10.5"/>'
    + '<path class="axc-mark" d="M6.8 12.6l3.3 3.3L17.2 9"/>'
    + '</svg>';
}
function showSuccess(msg){
  try{
    const old=document.querySelector('.ax-success');
    if(old) old.remove();
    const el=document.createElement('div');
    el.className='ax-success';
    el.setAttribute('role','status');
    el.innerHTML=_axSuccessSvg()+'<span></span>';
    el.querySelector('span').textContent=msg;
    document.body.appendChild(el);
    requestAnimationFrame(function(){ requestAnimationFrame(function(){ el.classList.add('show'); }); });
    setTimeout(function(){
      el.classList.remove('show');
      setTimeout(function(){ if(el.parentNode) el.remove(); },340);
    },1750);
  }catch(e){}
}

// ── Confeti ligero: ráfaga corta desde abajo-centro, para éxitos pequeños ──
// (el confeti grande de las metas, launchConfetti(), se queda como estaba)
function launchConfettiLight(){
  try{
    if(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const canvas=document.createElement('canvas');
    canvas.style.cssText='position:fixed;inset:0;z-index:1150;pointer-events:none;';
    canvas.width=window.innerWidth; canvas.height=window.innerHeight;
    document.body.appendChild(canvas);
    const ctx=canvas.getContext('2d');
    const colors=['#00b4d8','#F59E0B','#10B981','#EF4444','#7C3AED','#F97316'];
    const W=canvas.width, H=canvas.height;
    const particles=Array.from({length:36},function(){
      return {
        x:W/2+(Math.random()-.5)*W*.55,
        y:H*.82,
        vx:(Math.random()-.5)*7,
        vy:-(5.5+Math.random()*7),
        w:5+Math.random()*6, h:3+Math.random()*4,
        color:colors[Math.floor(Math.random()*colors.length)],
        rot:Math.random()*Math.PI*2, vrot:(Math.random()-.5)*.3,
        shape:Math.random()>.5?'circle':'rect'
      };
    });
    const start=Date.now();
    (function animate(){
      ctx.clearRect(0,0,W,H);
      const el=Date.now()-start;
      const alpha=el>950?Math.max(0,1-(el-950)/450):1;
      if(alpha<=0){ if(canvas.parentNode) canvas.remove(); return; }
      particles.forEach(function(p){
        p.x+=p.vx; p.y+=p.vy; p.vy+=.24; p.rot+=p.vrot;
        ctx.save(); ctx.globalAlpha=alpha; ctx.translate(p.x,p.y); ctx.rotate(p.rot);
        ctx.fillStyle=p.color;
        if(p.shape==='circle'){ ctx.beginPath(); ctx.arc(0,0,p.w/2,0,Math.PI*2); ctx.fill(); }
        else ctx.fillRect(-p.w/2,-p.h/2,p.w,p.h);
        ctx.restore();
      });
      requestAnimationFrame(animate);
    })();
    setTimeout(function(){ if(canvas.parentNode) canvas.remove(); },1500);
  }catch(e){}
}

// ── Skeleton loaders ──
function skelRows(n){
  let h='';
  for(let i=0;i<n;i++){
    h+='<div class="skel-row"><div class="skel skel-ava"></div>'
      +'<div class="skel-lines"><div class="skel skel-line"></div><div class="skel skel-line w60"></div></div></div>';
  }
  return h;
}
function skelTiles(n){
  let h='';
  for(let i=0;i<n;i++){
    h+='<div class="skel-tile"><div class="skel skel-ava"></div><div class="skel skel-line"></div></div>';
  }
  return h;
}
// Skeletons de "Mis vales" y comisiones mientras el primer tirón a la nube
// llega. renderMyVales() los pisa en cuanto haya datos locales reales.
function showSkeletonVales(){
  try{
    if(!activeGestorId) return;
    const c=document.getElementById('gestorMyVales');
    if(c && !getVales().some(function(v){ return v.gestorId===activeGestorId; })) c.innerHTML=skelRows(3);
    const k=document.getElementById('gestorComisionList');
    if(k && !k.innerHTML.trim()) k.innerHTML=skelRows(2);
  }catch(e){}
}

// ── Modo alto contraste (pleno sol) ──
function applyContrast(on){
  document.body.classList.toggle('contrast',on);
  try{ localStorage.setItem('axon_contrast',on?'on':'off'); }catch(e){}
  const s=document.getElementById('pfContrastState');
  if(s){ s.textContent=on?'ON':'OFF'; s.classList.toggle('off',!on); }
}
function toggleContrast(){
  applyContrast(!document.body.classList.contains('contrast'));
  haptic(8);
}

// ── Header glass al hacer scroll ──
(function(){
  const h=document.querySelector('header');
  if(!h) return;
  let ticking=false;
  const upd=function(){
    ticking=false;
    h.classList.toggle('ax-scrolled',(window.scrollY||document.documentElement.scrollTop||0)>8);
  };
  window.addEventListener('scroll',function(){
    if(ticking) return;
    ticking=true;
    requestAnimationFrame(upd);
  },{passive:true});
  upd();
})();

// ── Hero de color: utilidades para derivar tintes del color del gestor ──
function _hexToRgb(hex){
  hex=String(hex||'').replace('#','').trim();
  if(hex.length===3) hex=hex.split('').map(function(c){ return c+c; }).join('');
  const n=parseInt(hex,16);
  if(isNaN(n)||hex.length!==6) return [0,109,138];
  return [(n>>16)&255,(n>>8)&255,n&255];
}
function _mixHex(hex,target,f){
  const c=_hexToRgb(hex);
  return 'rgb('+Math.round(c[0]+(target[0]-c[0])*f)+','+Math.round(c[1]+(target[1]-c[1])*f)+','+Math.round(c[2]+(target[2]-c[2])*f)+')';
}
function _rgbaHex(hex,a){
  const c=_hexToRgb(hex);
  return 'rgba('+c[0]+','+c[1]+','+c[2]+','+a+')';
}
// ══ v218 · PASTEL SÓLIDO (no translúcido) ════════════════════════════════
// Queja del usuario: el relleno rgba(color,.08/.16) se ve "traslúcido", y con
// tanta mezcla al blanco los pasteles de colores distintos acababan pareciendo
// IGUALES ("los colores se repiten"). Ahora el relleno es un color OPACO:
//   · claro  → PASTEL_MAP (20 pasteles a mano, bien distintos entre sí) o,
//     para hexes fuera de la paleta, mezcla sólida 62% blanco;
//   · oscuro → v221: el COLOR PLENO del gestor oscurecido solo un 32% hacia
//     la noche (#0F172A): tinte profundo pero VIVO (la mezcla 72% anterior
//     apagaba los colores hasta casi negro y el usuario lo descartó).
const _PASTEL_MAP = {
  '#2563EB':'#A0BFF7', // azul → periwinkle
  '#7C3AED':'#C9B4F6', // violeta
  '#059669':'#A9E3CB', // esmeralda
  '#DC2626':'#F5B3B3', // rojo
  '#D97706':'#F6D5A7', // ámbar
  '#0891B2':'#A8DDED', // cian
  '#BE185D':'#F3B4CE', // fucsia
  '#4F46E5':'#BFC0F7', // índigo
  '#65A30D':'#D4E8A6', // lima
  '#0D9488':'#A6DED8', // teal
  '#EA580C':'#F8C8A6', // naranja
  '#7E22CE':'#D0B2EC', // uva
  '#0284C7':'#A8E2F2', // cielo (más cian que "azul" para no confundirse)
  '#B45309':'#E8C9AC', // marrón
  '#BE123C':'#F2B7C4', // granate
  '#15803D':'#B4DEC0', // bosque
  '#9333EA':'#DDBAFA', // púrpura
  '#C026D3':'#EFB4F2', // magenta
  '#1D4ED8':'#C3D2F2', // azul rey (más grisáceo que "azul")
  '#334155':'#C2CCDA', // pizarra
};
function _pastelClaro(hex){
  const k=String(hex||'').toUpperCase();
  return _PASTEL_MAP[k]||_mixHex(k,[255,255,255],.62);
}
function _pastelOscuro(hex){
  // v221 · «color vivo en oscuro» — queja del usuario: con la mezcla 72% hacia
  // la noche las tarjetas quedaban NEGRAS y "perdían vida". Ahora el color
  // ORIGINAL (pleno, con todo su croma) manda: 68% color + 32% noche →
  // tinte profundo pero claramente VIVO, con texto blanco legible (≥5:1).
  return _mixHex(hex||'#006d8a',[15,23,42],.32);
}
// Variables para elementos con relleno pastel gestionado por CSS (clase .pf-fill).
// Devuelve '' para la Tienda (queda con la superficie neutra del tema).
function _pfVars(g){
  if(!g||g._tienda) return '';
  const b=g.color||'#006d8a';
  return '--pfL:'+_pastelClaro(b)+';--pfD:'+_pastelOscuro(b)+';';
}
function gestorHeroVars(g){
  // v226 · Receta «tarjeta 3D» del mockup aprobado: degradado 135° del pastel
  // claro (--g1) al COLOR PLENO del gestor (--g2), tinta oscura derivada
  // (--gink) para el nombre sobre el vidrio, acento medio (--gacc2) para
  // «Entrar», tinte translúcido (--gacc) para los círculos y rgb de sombra
  // (--gsh) del mismo tono. --gbd se conserva por compatibilidad.
  const base=(g&&g.color)||'#006d8a';
  return '--g1:'+_pastelClaro(base)
    +';--gbd:'+_mixHex(base,[255,255,255],.42)
    +';--g2:'+base
    +';--gink:'+_mixHex(base,[0,0,0],.55)
    +';--gacc:'+_rgbaHex(base,.24)
    +';--gacc2:'+_mixHex(base,[0,0,0],.28)
    +';--gsh:'+_hexToRgb(_mixHex(base,[0,0,0],.72)).join(',');
}

// ── Tab bar inferior ──
function _setTab(name){
  document.querySelectorAll('#tabbar .tab-btn').forEach(function(b){
    b.classList.toggle('active',b.dataset.tab===name);
  });
}
function tabGo(name){
  haptic(8);
  if(name==='perfil'){ _setTab('perfil'); openPerfil(); return; }
  closePerfil();
  if(name==='catalogo'){
    _setTab('catalogo');
    openGestorCatalog();
    return;
  }
  if(name==='vales'){
    if(!activeGestorId){ showToast('Selecciona tu nombre primero'); _setTab('inicio'); return; }
    _setTab('vales');
    const sec=document.getElementById('gestorMyValesSection');
    if(sec) sec.scrollIntoView({behavior:'smooth',block:'start'});
    return;
  }
  _setTab('inicio');
  window.scrollTo({top:0,behavior:'smooth'});
}
// Scrollspy ligero: Inicio ↔ Mis vales según qué se ve en pantalla
(function(){
  let ticking=false;
  window.addEventListener('scroll',function(){
    if(ticking) return;
    ticking=true;
    requestAnimationFrame(function(){
      ticking=false;
      const sh=document.getElementById('perfilSheet');
      if(sh && sh.classList.contains('open')) return;
      const vales=document.getElementById('gestorMyValesSection');
      if(!vales || vales.style.display==='none' || !vales.offsetParent){ _setTab('inicio'); return; }
      const r=vales.getBoundingClientRect();
      _setTab(r.top < window.innerHeight*0.45 ? 'vales' : 'inicio');
    });
  },{passive:true});
})();

// ── Hoja de perfil ──
function _pfRefreshStates(){
  const dark=document.body.classList.contains('dark');
  const ts=document.getElementById('pfThemeState');
  if(ts){ ts.textContent=dark?'ON':'OFF'; ts.classList.toggle('off',!dark); }
  const ti=document.getElementById('pfThemeIco');
  if(ti) ti.textContent=dark?'☀️':'🌙';
  const cs=document.getElementById('pfContrastState');
  if(cs){
    const on=document.body.classList.contains('contrast');
    cs.textContent=on?'ON':'OFF'; cs.classList.toggle('off',!on);
  }
}
function openPerfil(){
  const sh=document.getElementById('perfilSheet');
  if(!sh) return;
  const bd=document.getElementById('pfBackdrop');
  if(bd) bd.classList.add('open');
  document.body.classList.add('pf-open');   // v78: esconde el banner de instalación mientras la hoja está abierta
  const g=activeGestorId?gestorOf(activeGestorId):null;
  const av=document.getElementById('pfAvatar');
  const nm=document.getElementById('pfName');
  const sb=document.getElementById('pfSub');
  if(g){
    av.textContent=g.initials||'?';
    av.style.background=g.color||'var(--gray-400)';
    nm.textContent=g.name;
    sb.textContent='Gestor · sesión activa en este dispositivo';
  }else{
    av.textContent='?';
    av.style.background='var(--gray-400)';
    nm.textContent='Sin gestor seleccionado';
    sb.textContent='Elige tu nombre para empezar';
  }
  const vb=document.getElementById('versionBadge');
  const ver=document.getElementById('pfVer');
  if(ver) ver.textContent='AXONTECH · '+(vb?vb.textContent.trim():'');
  _pfRefreshStates();
  sh.classList.add('open');
}
function closePerfil(){
  const sh=document.getElementById('perfilSheet');
  if(sh) sh.classList.remove('open');
  const bd=document.getElementById('pfBackdrop');
  if(bd) bd.classList.remove('open');
  document.body.classList.remove('pf-open');   // v78
}
function pfTheme(){ toggleTheme(); _pfRefreshStates(); haptic(8); }
function pfContrast(){ toggleContrast(); _pfRefreshStates(); }
function pfNotifs(){ closePerfil(); openNotifsModal(); }
function pfTasa(){ closePerfil(); openTasaModal(); }
function pfChangeGestor(){ closePerfil(); haptic(10); changeGestor(); }
// Cerrar la hoja con Escape (accesibilidad)
document.addEventListener('keydown',function(e){
  if(e.key==='Escape') closePerfil();
});

// ── Boot: alto contraste guardado ──
applyContrast(localStorage.getItem('axon_contrast')==='on');

// ── v78: el banner de instalación se esconde mientras haya un modal abierto
// (se peleaba por la misma esquina inferior que los botones del modal).
(function(){
  if(!('MutationObserver' in window)) return;
  const mo=new MutationObserver(function(){
    let open=false;
    try{ open=!!document.querySelector('.modal-bg.show'); }catch(e){}
    document.body.classList.toggle('ax-modal-open',open);
  });
  mo.observe(document.body,{attributes:true,subtree:true,attributeFilter:['class']});
})();


// ══════════════════════════════════════════════════════════════════════
//  v209 — MEJORAS FINALES
//  1. Notificación completa de vales nuevos (admin): sonido + vibración +
//     notificación del navegador con nombre del gestor y productos.
//  2. Exportar reportes desde Estadísticas: CSV (Excel) de ventas,
//     comisiones y stock + reporte PDF imprimible.
//  3. Modo SOLO LECTURA: segundo acceso sin permiso de escritura para
//     los dueños que solo quieren mirar.
//  4. Respaldo a la nube desde el admin (lo pesado vive en Code.gs).
// ══════════════════════════════════════════════════════════════════════

// ── 1. NOTIFICACIÓN DE VALES NUEVOS (admin) ──────────────────────────
// El poll ya detectaba el vale nuevo y solo tocaba el pitido. Ahora avisa
// de verdad: notificación del navegador (via service worker, llega aunque
// la pestaña esté en segundo plano), vibración y sonido. Respeta:
//   · axon_notif_vales = '0'  → apagado (toggle en Config)
//   · permiso de notificaciones no concedido → solo sonido/vibración
//   · primera carga del día   → se marca todo como visto, sin spam
var __notifValesListos = false;   // se levanta tras el PRIMER poll completo

function _notifValeNuevo(v) {
  try {
    if (localStorage.getItem('axon_notif_vales') === '0') return;
    if (!__notifValesListos) return;          // arranque: nada de spam
    const prodNames = (v.valeProductos || []).map(p => p.qty > 1 ? `${p.qty}x ${p.name || ''}` : (p.name || '')).join(', ');
    let quien = 'un gestor';
    try { const g = (typeof gestorOf === 'function') ? gestorOf(v.gestorId) : null; if (g && g.name) quien = g.name; } catch (e) {}
    const cuerpo = `${prodNames || 'Vale nuevo'}\nVale #${(typeof valeNumStr === 'function') ? valeNumStr(v) : v.id}`;
    if (typeof sendBrowserNotif === 'function') sendBrowserNotif('🧾 Vale nuevo de ' + quien, cuerpo);
    if (typeof playSound === 'function') playSound('newVale');
    if (typeof haptic === 'function') haptic([10, 40, 16]);
  } catch (e) { console.warn('[notif-vale]', e && e.message); }
}

function toggleNotifVales(btn) {
  const off = localStorage.getItem('axon_notif_vales') === '0';
  localStorage.setItem('axon_notif_vales', off ? '1' : '0');
  if (off && typeof requestNotifPermission === 'function') requestNotifPermission();
  showToast(off ? '🔔 Avisos de vales nuevos activados' : '🔕 Avisos de vales nuevos apagados');
  if (btn) { btn.textContent = off ? '🔔 Activados' : '🔕 Apagados'; }
  try { _pintarEstadoNotifVales(); } catch (e) {}
}
function _pintarEstadoNotifVales() {
  const el = document.getElementById('notifValesBtn'); if (!el) return;
  const off = localStorage.getItem('axon_notif_vales') === '0';
  el.textContent = off ? '🔕 Apagados' : '🔔 Activados';
  if (typeof Notification !== 'undefined' && Notification.permission !== 'granted') {
    const p = document.getElementById('notifValesPermiso'); if (p) p.style.display = 'block';
  }
}

// ── 2. EXPORTAR CSV / PDF (Estadísticas) ─────────────────────────────
// CSV con BOM UTF-8 y separador ';' — Excel en español lo abre con doble
// clic sin tocar nada. Sin librerías: Blob + link de descarga.
function _csvCelda(x) {
  const s = String(x == null ? '' : x).replace(/\r?\n/g, ' ').replace(/"/g, '""');
  return (s.indexOf(';') !== -1 || s.indexOf('"') !== -1) ? `"${s}"` : s;
}
function _csvDescargar(nombre, filas) {
  try {
    const csv = '\uFEFF' + filas.map(f => f.map(_csvCelda).join(';')).join('\r\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = nombre;
    document.body.appendChild(a); a.click();
    setTimeout(() => { try { URL.revokeObjectURL(a.href); a.remove(); } catch (e) {} }, 400);
    showToast('📤 ' + nombre + ' descargado');
    if (typeof haptic === 'function') haptic(10);
  } catch (e) { console.warn('[csv]', e); showToast('No se pudo generar el archivo'); }
}
function _statsFechas() {
  const from = (document.getElementById('statsDateFrom') || {}).value || '';
  const to = (document.getElementById('statsDateTo') || {}).value || '';
  return { from, to };
}
function _valesFiltradosStats() {
  const { from, to } = _statsFechas();
  let vales = getVales() || [];
  if (from) vales = vales.filter(v => _fechaEfectiva(v) >= from);
  if (to) vales = vales.filter(v => _fechaEfectiva(v) <= to);
  return vales;
}
const _ESTADO_LBL = { pending: 'Pendiente', assigned: 'En calle', delivered: 'Por confirmar', pending_payment: 'Por cobrar', confirmed: 'Confirmado', cancelled: 'Anulado' };
function _valeTotalTxt(v) {
  const p = (typeof _partesMonetarias === 'function') ? _partesMonetarias(v.total) : { usd: 0, mn: 0 };
  let s = p.usd ? '$' + (Math.round(p.usd * 100) / 100) + ' USD' : '';
  if (p.mn) s += (s ? ' + ' : '') + Math.round(p.mn).toLocaleString('es-ES') + ' MN';
  return s || '—';
}
function exportarCSV(tipo) {
  try {
    const hoy = new Date().toISOString().slice(0, 10);
    if (tipo === 'ventas') {
      const vales = _valesFiltradosStats();
      const filas = [['Fecha', 'Vale', 'Estado', 'Gestor', 'Mensajero', 'Productos', 'Total', 'Cobrado']];
      vales.slice().sort((a, b) => new Date(a.ts) - new Date(b.ts)).forEach(v => {
        let g = '—', m = '—';
        try { const gg = gestorOf(v.gestorId); g = (gg && gg.name) || (esValeDeLaTienda(v) ? 'Tienda (venta directa)' : g); } catch (e) {}
        try { const mm = mensajeroOf(v.mensajeroId); m = (mm && mm.name) || m; } catch (e) {}
        const prods = (v.valeProductos || []).map(p => `${p.qty}x ${p.name || ''}`).join(' + ');
        filas.push([_fechaEfectiva(v), 'V-' + ((typeof valeNumStr === 'function') ? valeNumStr(v) : v.id), _ESTADO_LBL[v.status] || v.status || '', g, m, prods, _valeTotalTxt(v), v.status === 'confirmed' ? 'Sí' : '']);
      });
      if (filas.length === 1) { showToast('No hay ventas en ese período'); return; }
      _csvDescargar('ventas_' + (hoy) + '.csv', filas);
    } else if (tipo === 'comisiones') {
      const vales = _valesFiltradosStats().filter(v => v.status === 'confirmed');
      const filas = [['Gestor', 'Vales confirmados', 'Comisión USD', 'Comisión MN', 'Pagada']];
      const porGestor = {};
      vales.forEach(v => {
        const gid = (esValeDeLaTienda && esValeDeLaTienda(v)) ? 'tienda' : v.gestorId;
        if (!porGestor[gid]) porGestor[gid] = { n: 0, usd: 0, mn: 0, pag: 0, tot: 0 };
        porGestor[gid].n++;
        porGestor[gid].tot++;
        if (v.commissionPaid) porGestor[gid].pag++;
        try { const cp = (typeof getValeCommissionParts === 'function') ? getValeCommissionParts(v) : null; if (cp && cp.total) { if (cp.currency === 'MN') porGestor[gid].mn += cp.total; else porGestor[gid].usd += cp.total; } } catch (e) {}
      });
      Object.keys(porGestor).forEach(gid => {
        let nombre = '—';
        if (gid === 'tienda') nombre = 'Tienda (venta directa)';
        else { try { const g = gestorOf(gid); if (g && g.name) nombre = g.name; } catch (e) {} }
        const d = porGestor[gid];
        filas.push([nombre, d.n, d.usd ? Math.round(d.usd * 100) / 100 : '0', d.mn ? Math.round(d.mn) : '0', d.pag + '/' + d.tot]);
      });
      if (filas.length === 1) { showToast('No hay comisiones en ese período'); return; }
      _csvDescargar('comisiones_' + hoy + '.csv', filas);
    } else {
      const prods = getProductos() || [];
      const cats = getCategorias() || [];
      const catNombre = id => { const c = cats.find(x => x.id == id); return c ? c.name : ''; };
      const filas = [['Producto', 'Categoría', 'Stock', 'Precio', 'Comisión', 'Puntos', 'Garantía']];
      prods.slice().sort((a, b) => String(a.name).localeCompare(String(b.name), 'es')).forEach(p => {
        filas.push([p.name || '', catNombre(p.catId), p.stock == null ? '' : p.stock, p.precio || '', p.comision || '', p.puntos || '', p.garantia || '']);
      });
      if (!prods.length) { showToast('No hay productos'); return; }
      _csvDescargar('stock_' + hoy + '.csv', filas);
    }
  } catch (e) { console.warn('[exportarCSV]', e); showToast('Error al exportar'); }
}
// Reporte PDF: se llena una hoja oculta de impresión y se abre el diálogo
// del sistema (en Android/Mac/iOS: "Guardar como PDF"). Cero dependencias.
function exportarPDF() {
  try {
    const rep = document.getElementById('printReport'); if (!rep) { showToast('Reporte no disponible'); return; }
    const { from, to } = _statsFechas();
    const vales = _valesFiltradosStats();
    let nombreMarca = 'AXONTECH';
    try { nombreMarca = _marcaNombre(getMarca()); } catch (e) {}
    const total = _vxSumaTotales(vales.filter(v => v.status === 'confirmed'));
    const pend = _vxSumaTotales(vales.filter(v => v.status !== 'confirmed' && v.status !== 'cancelled'));
    const gestores = getGestores().slice();
    let filasGestor = '';
    gestores.forEach(g => {
      const propios = vales.filter(v => String(v.gestorId) === String(g.id));
      if (!propios.length) return;
      const s = _vxSumaTotales(propios.filter(v => v.status === 'confirmed'));
      const conf = propios.filter(v => v.status === 'confirmed').length;
      filasGestor += `<tr><td>${escapeHTML(g.name)}</td><td>${propios.length}</td><td>${conf}</td><td>${_vxMoney(s.usd)}</td></tr>`;
    });
    const prodCount = {};
    vales.forEach(v => (v.valeProductos || []).forEach(({ id, qty }) => {
      if (!prodCount[id]) prodCount[id] = { qty: 0, c: 0 }; prodCount[id].qty += qty;
      if (v.status === 'confirmed') prodCount[id].c += qty;
    }));
    let filasProd = Object.entries(prodCount).sort(([, a], [, b]) => b.qty - a.qty).slice(0, 15).map(([id, d]) => {
      const p = productoOf(parseInt(id));
      return `<tr><td>${p ? escapeHTML(p.name) : 'Producto ' + id}</td><td>${d.qty}</td><td>${d.c}</td></tr>`;
    }).join('');
    const periodo = (from || to) ? `${from || '…'} → ${to || '…'}` : 'todo el historial';
    rep.innerHTML = `
      <div class="pr-head"><h1>${escapeHTML(nombreMarca)} · Reporte de ventas</h1>
      <div class="pr-sub">Período: ${escapeHTML(periodo)} · Generado ${new Date().toLocaleString('es-ES')}</div></div>
      <div class="pr-cards">
        <div class="pr-card"><span>Vales</span><b>${vales.length}</b></div>
        <div class="pr-card"><span>Confirmados</span><b>${vales.filter(v => v.status === 'confirmed').length}</b></div>
        <div class="pr-card"><span>Cobrado</span><b>${_vxMoney(total.usd)}${total.mn ? ' + ' + Math.round(total.mn) + ' MN' : ''}</b></div>
        <div class="pr-card"><span>Por cobrar</span><b>${_vxMoney(pend.usd)}${pend.mn ? ' + ' + Math.round(pend.mn) + ' MN' : ''}</b></div>
      </div>
      <h2>Ventas por gestor</h2>
      <table><thead><tr><th>Gestor</th><th>Vales</th><th>Confirmados</th><th>Cobrado</th></tr></thead>
      <tbody>${filasGestor || '<tr><td colspan="4">Sin ventas en el período</td></tr>'}</tbody></table>
      <h2>Productos más vendidos</h2>
      <table><thead><tr><th>Producto</th><th>Vendidos</th><th>Entregados</th></tr></thead>
      <tbody>${filasProd || '<tr><td colspan="3">Sin datos</td></tr>'}</tbody></table>`;
    document.body.classList.add('printing-report');
    showToast('Abriendo impresión → elige "Guardar como PDF"');
    setTimeout(() => {
      try { window.print(); } catch (e) {}
      setTimeout(() => document.body.classList.remove('printing-report'), 500);
    }, 150);
  } catch (e) { console.warn('[exportarPDF]', e); showToast('No se pudo generar el reporte'); }
}

// ── 3. MODO SOLO LECTURA ─────────────────────────────────────────────
// Segunda contraseña para dueños/companeros que solo deben MIRAR. La
// clave vive hasheada en axon_admin_ro_hash (se crea desde Config).
const _RO_HASH_KEY = 'axon_admin_ro_hash';
function _esSoloLectura() { return document.body.classList.contains('ronly'); }
async function verifyPassROAsync(input) {
  const stored = localStorage.getItem(_RO_HASH_KEY);
  if (!stored || !input) return false;
  try { return (await _hashPass(input)) === stored; } catch (e) { return false; }
}
function submitPassRO() {
  const val = (document.getElementById('passInput') || {}).value || '';
  verifyPassROAsync(val).then(ok => {
    if (ok) {
      // Orden importa: activar la sesión ANTES de cerrar el modal —
      // closePassModal() redirige al index si ve adminActive en falso.
      activarSoloLectura();
      closePassModal();
      if (typeof playSound === 'function') playSound('login');
    } else {
      const pe = document.getElementById('passError'); if (pe) pe.style.display = 'block';
    }
  });
}
function activarSoloLectura() {
  adminActive = true;                       // se ven todos los paneles…
  document.body.classList.add('ronly');     // …pero nada se puede guardar
  try { sessionStorage.setItem('axon_ro', '1'); } catch (e) {}
  const al = document.getElementById('adminLabel'); if (al) al.style.display = 'none';
  const ro = document.getElementById('roLabel'); if (ro) ro.style.display = 'flex';
  const bl = document.getElementById('btnLogout'); if (bl) bl.style.display = 'inline-flex';
  showToast('👤 Modo solo lectura: puedes ver todo, no guardar');
  adminTab('vales');
  updateAdminBadge();
}
function _salirSoloLectura() {
  document.body.classList.remove('ronly');
  try { sessionStorage.removeItem('axon_ro'); } catch (e) {}
  const ro = document.getElementById('roLabel'); if (ro) ro.style.display = 'none';
}
async function guardarRoPassCfg() {
  const inp = document.getElementById('roPassCfg');
  const val = (inp && inp.value || '').trim();
  if (val.length < 4) { showToast('Mínimo 4 caracteres'); return; }
  try {
    const h = await _hashPass(val);
    localStorage.setItem(_RO_HASH_KEY, h);
    if (inp) inp.value = '';
    showToast('✅ Contraseña de solo lectura creada');
    _pintarRoCfg();
  } catch (e) { showToast('No se pudo guardar'); }
}
function quitarRoPassCfg() {
  if (_esSoloLectura()) return;
  localStorage.removeItem(_RO_HASH_KEY);
  showToast('Acceso de solo lectura eliminado');
  _pintarRoCfg();
}
function _pintarRoCfg() {
  const el = document.getElementById('roCfgEstado'); if (!el) return;
  const hay = !!localStorage.getItem(_RO_HASH_KEY);
  el.textContent = hay ? 'Activo — ya se puede entrar con "Entrar solo lectura" en la pantalla de contraseña' : 'Sin contraseña — actívala para dar acceso de mirar sin tocar';
  const b = document.getElementById('roCfgQuitar'); if (b) b.style.display = hay ? 'inline-flex' : 'none';
}
// Cinturón: bloquea TODA escritura a la nube en modo solo lectura en un
// solo punto (el interceptor v140). La cola local (_enqueueSB) también.
(function () {
  try {
    const _f0 = window.fetch.bind(window);
    window.fetch = function (url, opts) {
      try {
        if (_esSoloLectura()) {
          const u = String((url && url.url) || url || '');
          const m = String((opts && opts.method) || 'GET').toUpperCase();
          if (u.indexOf(_GS_REST) === 0 && m !== 'GET' && m !== 'HEAD') {
            return Promise.resolve(new Response(JSON.stringify({ __error: 'solo lectura' }), { status: 403, headers: { 'Content-Type': 'application/json' } }));
          }
        }
      } catch (e) {}
      return _f0(url, opts);
    };
  } catch (e) {}
  // La cola de escritura local tampoco arranca en solo lectura.
  try {
    const _orig = _enqueueSB;
    _enqueueSB = function (path, value, method, callback) {
      if (_esSoloLectura()) { showToast('🔒 Solo lectura: no se guardan cambios'); return; }
      return _orig(path, value, method, callback);
    };
  } catch (e) {}
})();

// ── 4. RESPALDO (la copia la hace Code.gs; aquí solo botones) ────────
async function _backupRpc(fn, extra) {
  const res = await fetch(`${_GS_REST}/rpc/${fn}`, { method: 'POST', headers: _GS_HDRS, body: JSON.stringify(extra || {}) });
  const j = await res.json().catch(() => null);
  if (!res.ok || (j && j.__error)) throw new Error((j && j.__error) || ('HTTP ' + res.status));
  return j;
}
function _backupEstadoTxt(j) {
  if (!j) return 'Sin conexión con la hoja';
  const t = j.ultimo ? new Date(j.ultimo).toLocaleString('es-ES') : null;
  const trig = j.trigger ? ' · semanal activo' : ' · semanal inactivo';
  return (t ? 'Último respaldo: ' + t : 'Aún no hay respaldos') + trig + (j.archivos != null ? ` · ${j.archivos} guardados` : '');
}
async function backupRefrescarUI() {
  const el = document.getElementById('backupEstado'); if (!el) return;
  el.textContent = 'Consultando…';
  try { const j = await _backupRpc('backup_info'); el.textContent = _backupEstadoTxt(j); }
  catch (e) { el.textContent = '⚠ ' + (e.message || 'Sin conexión con la hoja'); }
}
async function backupAhoraUI() {
  const el = document.getElementById('backupEstado'); if (!el) return;
  el.textContent = 'Respaldando… (puede tardar un poco)';
  try {
    const j = await _backupRpc('backup_now');
    showToast('☁️ Respaldo creado: ' + (j && j.nombre ? j.nombre : 'OK'));
    el.textContent = _backupEstadoTxt(j);
  } catch (e) { el.textContent = '⚠ ' + (e.message || 'fallo'); showToast('No se pudo respaldar'); }
}
async function backupTriggerUI(on) {
  const el = document.getElementById('backupEstado'); if (!el) return;
  el.textContent = on ? 'Activando respaldo semanal…' : 'Desactivando…';
  try { const j = await _backupRpc('backup_trigger', { p_on: !!on }); el.textContent = _backupEstadoTxt(j); showToast(on ? '☁️ Respaldo semanal activado' : 'Respaldo semanal desactivado'); }
  catch (e) { el.textContent = '⚠ ' + (e.message || 'fallo'); }
}
